import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import aaImage from "../assets/AA.png";
import bbImage from "../assets/bb.jpeg";

const Introduction = () => {
  const [advocate, setAdvocate] = useState({
    username: 'advocate1',
    role: 'advocate',
    name: 'Bavani Sinde',
    photo: 'bb.jpeg',
    education: 'BA, LLB',
    address: 'Muddebihal'
  });

  useEffect(() => {
    const fetchAdvocateDetails = async () => {
      try {
        const username = localStorage.getItem('username');
        const role = localStorage.getItem('role');

        // Update with current user info if available
        if (username || role) {
          setAdvocate(prev => ({
            ...prev,
            username: username || prev.username,
            role: role || prev.role
          }));
        }
      } catch (error) {
        console.error('Error fetching advocate details:', error);
      }
    };

    fetchAdvocateDetails();
  }, []);

  return (
    <div
      style={{
        minHeight: "100vh",
        padding: "30px",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
        color: "white",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        textAlign: "center",
        backgroundImage: `url(${aaImage})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
      }}
    >
      <div style={{
        background: "rgba(255,255,255,0.1)",
        padding: "40px",
        borderRadius: "20px",
        boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "20px",
        backdropFilter: "blur(10px)",
        border: "1px solid rgba(255,255,255,0.2)"
      }}>
        <img
          src={bbImage}
          alt="Advocate"
          style={{
            width: "150px",
            height: "150px",
            borderRadius: "50%",
            border: "4px solid rgba(255,255,255,0.3)",
            objectFit: "cover",
            boxShadow: "0 5px 15px rgba(0,0,0,0.2)"
          }}
        />
        <div style={{ textAlign: "center" }}>
          <h1 style={{
            fontSize: "2.5rem",
            marginBottom: "10px",
            color: "#fff",
            textShadow: "2px 2px 4px rgba(0,0,0,0.3)"
          }}>
            {advocate.name}
          </h1>
          <p style={{
            fontSize: "1.5rem",
            color: "#fff",
            opacity: "0.9",
            margin: "0"
          }}>
            {advocate.education}
          </p>
          <p style={{
            fontSize: "1.2rem",
            color: "#fff",
            opacity: "0.8",
            margin: "0"
          }}>
            {advocate.address}
          </p>
          <Link to="/dashboard">
            <button style={{
              marginTop: "20px",
              padding: "10px 20px",
              backgroundColor: "rgba(255,255,255,0.2)",
              color: "#fff",
              border: "1px solid rgba(255,255,255,0.3)",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "1rem",
              backdropFilter: "blur(10px)"
            }}>
              Back to Dashboard
            </button>
          </Link>
        </div>
      </div>
    </div>
  );
};

export default Introduction;
