import React from "react";
import { Link } from "react-router-dom";
import ssImage from '../assets/AA.png';

const Home = () => {
  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      minHeight: "100vh",
      backgroundImage: `url(${ssImage})`,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      justifyContent: "center",
      alignItems: "center",
      textAlign: "center",
      padding: "20px",
      position: "relative",
      overflow: "hidden"
    }}>

      {/* Floating animated decorative elements */}
      <div style={{
        position: "absolute",
        width: "250px",
        height: "250px",
        background: "rgba(102,126,234,0.1)",
        borderRadius: "50%",
        top: "5%",
        left: "10%",
        animation: "float1 10s ease-in-out infinite alternate"
      }} />
      <div style={{
        position: "absolute",
        width: "200px",
        height: "200px",
        background: "rgba(118,75,162,0.15)",
        borderRadius: "50%",
        bottom: "10%",
        right: "15%",
        animation: "float2 12s ease-in-out infinite alternate-reverse"
      }} />
      <div style={{
        position: "absolute",
        width: "120px",
        height: "120px",
        background: "rgba(255,255,255,0.2)",
        borderRadius: "50%",
        top: "50%",
        left: "80%",
        animation: "float3 8s ease-in-out infinite alternate"
      }} />

      {/* Glass card */}
      <div style={{
        background: "rgba(255, 255, 255, 0.15)",
        backdropFilter: "blur(20px)",
        borderRadius: "30px",
        padding: "60px 50px",
        boxShadow: "0 25px 60px rgba(0,0,0,0.3)",
        maxWidth: "800px",
        width: "100%",
        position: "relative",
        zIndex: 2,
        border: "1px solid rgba(255,255,255,0.3)",
        animation: "fadeInUp 1s ease-out"
      }}>
        <h1 style={{
          fontSize: "3.5rem",
          color: "white",
          fontWeight: "bold",
          marginBottom: "20px",
          textShadow: "2px 2px 15px rgba(0,0,0,0.7)",
          animation: "floatTitle 4s ease-in-out infinite"
        }}>
          ⚖️ LexFlow – Digital Legal Case Management System
        </h1>

        <p style={{
          fontSize: "1.3rem",
          color: "white",
          lineHeight: "1.6",
          maxWidth: "650px",
          margin: "0 auto 40px",
          textShadow: "1px 1px 10px rgba(0,0,0,0.5)"
        }}>
          Streamline your legal practice with our comprehensive case management system.
          Manage cases, clients, billing, and communication all in one place.
        </p>

        <Link to="/login">
          <button style={{
            padding: "18px 55px",
            fontSize: "1.2rem",
            fontWeight: "bold",
            background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
            color: "white",
            border: "none",
            borderRadius: "50px",
            cursor: "pointer",
            boxShadow: "0 8px 25px rgba(102, 126, 234, 0.6)",
            transition: "all 0.4s ease",
            textDecoration: "none",
            display: "inline-block"
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = "translateY(-5px) scale(1.05)";
            e.target.style.boxShadow = "0 15px 40px rgba(102, 126, 234, 0.9)";
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = "translateY(0) scale(1)";
            e.target.style.boxShadow = "0 8px 25px rgba(102, 126, 234, 0.6)";
          }}>
            🚀 Get Started
          </button>
        </Link>
      </div>

      {/* Animations */}
      <style>
        {`
          @keyframes float1 {
            0% { transform: translateY(0) translateX(0); }
            50% { transform: translateY(-25px) translateX(15px); }
            100% { transform: translateY(0) translateX(0); }
          }

          @keyframes float2 {
            0% { transform: translateY(0) translateX(0); }
            50% { transform: translateY(-30px) translateX(-10px); }
            100% { transform: translateY(0) translateX(0); }
          }

          @keyframes float3 {
            0% { transform: translateY(0) translateX(0); }
            50% { transform: translateY(-20px) translateX(10px); }
            100% { transform: translateY(0) translateX(0); }
          }

          @keyframes floatTitle {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
          }

          @keyframes fadeInUp {
            0% { opacity: 0; transform: translateY(30px); }
            100% { opacity: 1; transform: translateY(0); }
          }
        `}
      </style>
    </div>
  );
};

export default Home;
