import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import ssImage from '../assets/AA.png';

const styles = `
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideIn {
  from { opacity: 0; transform: scale(0.9); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(0, 123, 255, 0.4); }
  70% { box-shadow: 0 0 0 10px rgba(0, 123, 255, 0); }
  100% { box-shadow: 0 0 0 0 rgba(0, 123, 255, 0); }
}

@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-10px); }
}

body, html {
  margin: 0;
  padding: 0;
  background-image: url(${ssImage});
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  height: 100%;
}

.login-container {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.login-container::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grain" width="100" height="100" patternUnits="userSpaceOnUse"><circle cx="25" cy="25" r="1" fill="rgba(255,255,255,0.1)"/><circle cx="75" cy="75" r="1" fill="rgba(255,255,255,0.1)"/><circle cx="50" cy="10" r="0.5" fill="rgba(255,255,255,0.1)"/></pattern></defs><rect width="100" height="100" fill="url(%23grain)"/></svg>');
  pointer-events: none;
}

.login-header {
  text-align: center;
  margin-bottom: 30px;
  color: white;
  z-index: 2;
  position: relative;
}

.login-header h1 {
  font-size: 3rem;
  font-weight: 700;
  margin: 0;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
  animation: float 3s ease-in-out infinite;
}

.login-header p {
  font-size: 1.2rem;
  margin: 10px 0 0 0;
  opacity: 0.9;
}

.login-card {
  background: linear-gradient(135deg, #DEB887 0%, #A0522D 100%);
  backdrop-filter: blur(10px);
  border: 2px solid #A0522D;
  border-radius: 20px;
  padding: 40px;
  width: 420px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15), 0 0 30px rgba(160, 82, 45, 0.5);
  animation: slideIn 0.8s ease-out, glow 2s ease-in-out infinite alternate;
  position: relative;
  z-index: 2;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.login-card:hover {
  transform: scale(1.05);
  box-shadow: 0 25px 50px rgba(0, 0, 0, 0.2), 0 0 40px rgba(160, 82, 45, 0.7);
}

@keyframes glow {
  from { box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15), 0 0 30px rgba(160, 82, 45, 0.5); }
  to { box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15), 0 0 40px rgba(160, 82, 45, 0.8); }
}

.form-group {
  margin-bottom: 25px;
  position: relative;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
  color: #333;
  font-size: 14px;
}

.form-group input,
.form-group select {
  width: 100%;
  padding: 15px 20px;
  border: 2px solid #e1e5e9;
  border-radius: 12px;
  font-size: 16px;
  transition: all 0.3s ease;
  background: #f8f9fa;
  box-sizing: border-box;
}

.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: #667eea;
  background: white;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
  transform: translateY(-2px);
}

.error-message {
  color: #e74c3c;
  font-size: 12px;
  margin-top: 5px;
  animation: fadeIn 0.3s;
  font-weight: 500;
}

.login-button {
  width: 100%;
  padding: 15px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 16px;
  font-weight: 600;
  position: relative;
  overflow: hidden;
}

.login-button::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  transition: left 0.5s;
}

.login-button:hover::before {
  left: 100%;
}

.login-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 25px rgba(102, 126, 234, 0.3);
}

.login-button:disabled {
  opacity: 0.7;
  cursor: not-allowed;
  transform: none;
}

.register-link {
  text-align: center;
  margin-top: 25px;
  color: #666;
  font-size: 14px;
}

.register-link a {
  color: #667eea;
  text-decoration: none;
  font-weight: 600;
  transition: color 0.3s ease;
}

.register-link a:hover {
  color: #764ba2;
  text-decoration: underline;
}

.role-selector {
  position: relative;
}

.role-selector::after {
  content: '▼';
  position: absolute;
  right: 15px;
  top: 50%;
  transform: translateY(-50%);
  color: #667eea;
  pointer-events: none;
}
`;

const styleSheet = document.createElement("style");
styleSheet.type = "text/css";
styleSheet.innerText = styles;
document.head.appendChild(styleSheet);

const Login = () => {
  const [role, setRole] = useState("Advocate");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const validateForm = () => {
    const newErrors = {};
    if (!username.trim()) {
      newErrors.username = "Username is required.";
    } else if (username.length < 3) {
      newErrors.username = "Username must be at least 3 characters.";
    } else if (!/^[a-zA-Z0-9_]+$/.test(username)) {
      newErrors.username = "Username can only contain letters, numbers, and underscores.";
    }

    if (!password) {
      newErrors.password = "Password is required.";
    } else if (password.length < 6) {
      newErrors.password = "Password must be at least 6 characters.";
    } else if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/.test(password)) {
      newErrors.password = "Password must contain at least one uppercase letter, one lowercase letter, and one number.";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrors({});
    if (!validateForm()) return;

    setIsLoading(true);
    console.log("Login data:", { role, username, password });

    try {
      let endpoint;
      if (role === "Advocate") {
        endpoint = "/login/advocate";
      } else if (role === "Client") {
        endpoint = "/login/client";
      } else if (role === "Staff") {
        endpoint = "/login/staff";
      }

      const response = await fetch(`http://localhost:5000${endpoint}`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ username, password }),
      });

      const data = await response.json();

      if (data.success) {
        alert("login successfully");
        localStorage.setItem("role", role.toLowerCase());
        localStorage.setItem("username", username);
        if (role === "Client") {
          localStorage.setItem("clientName", data.clientName);
          localStorage.setItem("clientId", data.clientId);
        } else if (role === "Staff") {
          localStorage.setItem("staffName", data.staffName);
          localStorage.setItem("advocateName", data.advocateName);
        }

        if (role === "Advocate") {
          navigate("/advocate-dashboard");
        } else if (role === "Client") {
          navigate("/client-dashboard");
        } else if (role === "Staff") {
          navigate("/staff-dashboard");
        }
      } else {
        alert("invalide usename and password");
        setErrors({ general: "Invalid credentials. Please check your username and password." });
      }
    } catch (error) {
      console.error("Login error:", error);
      setErrors({ general: "Login failed. Please try again." });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="login-container">
      <div className="login-header">
        <h1>Advocate LegalCaseBook</h1>
        <p>Secure Access Portal</p>
      </div>

      <div className="login-card">
        <h2 style={{ textAlign: "center", marginBottom: "30px", color: "#333", fontSize: "24px", fontWeight: "600" }}>
          Welcome Back
        </h2>

        {errors.general && (
          <div style={{
            color: "#e74c3c",
            marginBottom: "20px",
            padding: "12px 15px",
            border: "1px solid #e74c3c",
            borderRadius: "8px",
            backgroundColor: "#fdf2f2",
            animation: "fadeIn 0.5s",
            fontSize: "14px",
            fontWeight: "500"
          }}>
            {errors.general}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="form-group role-selector">
            <label>Role</label>
            <select
              value={role}
              onChange={(e) => setRole(e.target.value)}
            >
              <option value="Advocate">Advocate</option>
              <option value="Client">Client</option>
              <option value="Staff">Staff</option>
            </select>
          </div>

          <div className="form-group">
            <label>Username</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Enter your username"
              required
              style={{
                borderColor: errors.username ? "#e74c3c" : "#e1e5e9"
              }}
            />
            {errors.username && <div className="error-message">{errors.username}</div>}
          </div>

          <div className="form-group">
            <label>Password</label>
            <div style={{ position: 'relative' }}>
              <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter your password"
                required
                style={{
                  borderColor: errors.password ? "#e74c3c" : "#e1e5e9",
                  paddingRight: '45px'
                }}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                style={{
                  position: 'absolute',
                  right: '10px',
                  top: '50%',
                  transform: 'translateY(-50%)',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  fontSize: '18px',
                  color: '#667eea'
                }}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? "🙈" : "👁️"}
              </button>
            </div>
            {errors.password && <div className="error-message">{errors.password}</div>}
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className="login-button"
          >
            {isLoading ? "Authenticating..." : "Sign In"}
          </button>
        </form>

        {role === "Advocate" && (
          <div className="register-link">
            
          <span style={{ color: "white" }}>New to Advocate LegalCaseBook? </span>
            <a href="/register">Create Account</a>
          </div>
        )}
      </div>
    </div>
  );
};

export default Login;
