import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";

const Reports = () => {
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [reportType, setReportType] = useState('case_progress');
  const [clientName, setClientName] = useState('');

  useEffect(() => {
    // Get client name from localStorage
    const storedClientName = localStorage.getItem('clientName');
    if (storedClientName) {
      setClientName(storedClientName);
      fetchReports(storedClientName);
    }
  }, []);

  const fetchReports = async (client) => {
    try {
      const response = await fetch(`http://localhost:5000/reports/${client}`);
      if (response.ok) {
        const data = await response.json();
        setReports(data);
      }
    } catch (error) {
      console.error('Error fetching reports:', error);
    }
  };

  const generateReport = async () => {
    if (!clientName) {
      alert('Client name not found. Please log in again.');
      return;
    }

    setGenerating(true);
    try {
      const response = await fetch('http://localhost:5000/reports/generate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          clientName: clientName,
          reportType: reportType
        }),
      });

      const result = await response.json();
      if (result.success) {
        alert('Report generated successfully!');
        // Refresh reports list
        fetchReports(clientName);
      } else {
        alert(`Failed to generate report: ${result.message}`);
      }
    } catch (error) {
      console.error('Error generating report:', error);
      alert('Failed to generate report. Please try again.');
    } finally {
      setGenerating(false);
    }
  };

  const formatReportType = (type) => {
    const types = {
      'case_progress': 'Case Progress',
      'invoice': 'Invoice Summary',
      'legal_opinion': 'Legal Opinion',
      'settlement_proposal': 'Settlement Proposal'
    };
    return types[type] || type;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div style={{
      display: "flex",
      minHeight: "100vh",
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif"
    }}>
      {/* Left Sidebar */}
      <div style={{
        width: "280px",
        background: "burlywood",
        padding: "30px 20px",
        boxShadow: "2px 0 10px rgba(0,0,0,0.1)",
        position: "fixed",
        height: "100vh",
        overflowY: "auto"
      }}>
        <h2 style={{
          color: "white",
          textAlign: "center",
          marginBottom: "30px",
          fontSize: "1.5rem",
          textShadow: "1px 1px 2px rgba(0,0,0,0.3)"
        }}>
          Client Navigation
        </h2>
        <Link to="/client-case-details" style={{
          display: "block",
          padding: "15px 20px",
          marginBottom: "10px",
          background: "rgba(255,255,255,0.1)",
          color: "white",
          textDecoration: "none",
          borderRadius: "10px",
          fontSize: "16px",
          fontWeight: "bold",
          transition: "background 0.3s ease, transform 0.3s ease",
        }}>
          My Cases
        </Link>

        <Link to="/client-billing" style={{
          display: "block",
          padding: "15px 20px",
          marginBottom: "10px",
          background: "rgba(255,255,255,0.1)",
          color: "white",
          textDecoration: "none",
          borderRadius: "10px",
          fontSize: "16px",
          fontWeight: "bold",
          transition: "background 0.3s ease, transform 0.3s ease",
        }}>
          Billing
        </Link>
        <Link to="/client-communication" style={{
          display: "block",
          padding: "15px 20px",
          marginBottom: "10px",
          background: "rgba(255,255,255,0.1)",
          color: "white",
          textDecoration: "none",
          borderRadius: "10px",
          fontSize: "16px",
          fontWeight: "bold",
          transition: "background 0.3s ease, transform 0.3s ease",
        }}>
          Communication
        </Link>
        <Link to="/client-reports" style={{
          display: "block",
          padding: "15px 20px",
          marginBottom: "10px",
          background: "rgba(255,255,255,0.3)",
          color: "white",
          textDecoration: "none",
          borderRadius: "10px",
          fontSize: "16px",
          fontWeight: "bold",
          transition: "background 0.3s ease, transform 0.3s ease",
        }}>
          📊 Reports
        </Link>
      </div>

      {/* Main Content Area */}
      <div style={{
        marginLeft: "280px",
        flex: 1,
        padding: "40px",
        minHeight: "100vh"
      }}>
        <div style={{
          textAlign: "center",
          marginBottom: "30px",
          background: "rgba(255,255,255,0.9)",
          padding: "30px",
          borderRadius: "20px",
          boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
          position: "relative"
        }}>
          <button
            onClick={() => {
              localStorage.clear();
              window.location.href = '/';
            }}
            style={{
              position: "absolute",
              top: "20px",
              right: "20px",
              padding: "10px 20px",
              background: "linear-gradient(135deg, #dc3545 0%, #c82333 100%)",
              color: "white",
              border: "none",
              borderRadius: "8px",
              fontSize: "14px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            🔙 Back to Login
          </button>
          <h1 style={{
            color: "#333",
            fontSize: "2.5rem",
            marginBottom: "10px",
            textShadow: "2px 2px 4px rgba(0,0,0,0.1)"
          }}>
            📊 AI-Generated Reports
          </h1>
          <p style={{
            color: "#666",
            fontSize: "1.1rem",
            margin: 0
          }}>
            Get intelligent insights about your legal cases
          </p>
        </div>

        {/* Report Generation Section */}
        <div style={{
          background: "white",
          padding: "30px",
          borderRadius: "15px",
          boxShadow: "0 5px 20px rgba(0,0,0,0.1)",
          marginBottom: "30px"
        }}>
          <h2 style={{ color: "#333", marginBottom: "20px" }}>Generate New Report</h2>

          <div style={{ display: "flex", gap: "20px", alignItems: "center", flexWrap: "wrap" }}>
            <div style={{ flex: 1, minWidth: "200px" }}>
              <label style={{ display: "block", marginBottom: "8px", fontWeight: "bold", color: "#555" }}>
                Report Type:
              </label>
              <select
                value={reportType}
                onChange={(e) => setReportType(e.target.value)}
                style={{
                  width: "100%",
                  padding: "12px",
                  border: "2px solid #ddd",
                  borderRadius: "8px",
                  fontSize: "16px",
                  backgroundColor: "white"
                }}
              >
                <option value="case_progress">📈 Case Progress Report</option>
                <option value="invoice">💰 Invoice Summary</option>
                <option value="legal_opinion">⚖️ Legal Opinion</option>
                <option value="settlement_proposal">🤝 Settlement Proposal</option>
              </select>
            </div>

            <div style={{ display: "flex", alignItems: "end" }}>
              <button
                onClick={generateReport}
                disabled={generating}
                style={{
                  padding: "12px 30px",
                  background: generating ? "#ccc" : "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                  color: "white",
                  border: "none",
                  borderRadius: "8px",
                  fontSize: "16px",
                  fontWeight: "bold",
                  cursor: generating ? "not-allowed" : "pointer",
                  boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
                  transition: "transform 0.3s ease"
                }}
                onMouseEnter={(e) => !generating && (e.target.style.transform = "translateY(-2px)")}
                onMouseLeave={(e) => !generating && (e.target.style.transform = "translateY(0)")}
              >
                {generating ? "🤖 Generating..." : "🚀 Generate Report"}
              </button>
            </div>
          </div>
        </div>

        {/* Reports List */}
        <div style={{
          background: "white",
          padding: "30px",
          borderRadius: "15px",
          boxShadow: "0 5px 20px rgba(0,0,0,0.1)"
        }}>
          <h2 style={{ color: "#333", marginBottom: "20px" }}>Your Reports</h2>

          {reports.length === 0 ? (
            <div style={{
              textAlign: "center",
              padding: "40px",
              color: "#666",
              fontSize: "18px"
            }}>
              <p>📝 No reports generated yet.</p>
              <p>Generate your first AI-powered report above!</p>
            </div>
          ) : (
            <div style={{ display: "grid", gap: "20px" }}>
              {reports.map((report) => (
                <div
                  key={report.id}
                  style={{
                    border: "2px solid #e9ecef",
                    borderRadius: "12px",
                    padding: "25px",
                    backgroundColor: "#f8f9fa",
                    transition: "box-shadow 0.3s ease"
                  }}
                  onMouseEnter={(e) => (e.target.style.boxShadow = "0 8px 25px rgba(0,0,0,0.15)")}
                  onMouseLeave={(e) => (e.target.style.boxShadow = "none")}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", marginBottom: "15px" }}>
                    <div>
                      <h3 style={{ margin: "0 0 8px 0", color: "#333", fontSize: "1.3rem" }}>
                        {formatReportType(report.type)}
                      </h3>
                      <p style={{ margin: 0, color: "#666", fontSize: "0.9rem" }}>
                        Generated on {formatDate(report.generated_at)}
                      </p>
                    </div>
                    <div style={{
                      background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                      color: "white",
                      padding: "8px 16px",
                      borderRadius: "20px",
                      fontSize: "0.8rem",
                      fontWeight: "bold",
                      textTransform: "uppercase"
                    }}>
                      {formatReportType(report.type)}
                    </div>
                  </div>

                  <div style={{
                    backgroundColor: "white",
                    padding: "20px",
                    borderRadius: "8px",
                    border: "1px solid #dee2e6",
                    maxHeight: "300px",
                    overflowY: "auto",
                    lineHeight: "1.6",
                    color: "#333"
                  }}>
                    <pre style={{
                      whiteSpace: "pre-wrap",
                      wordWrap: "break-word",
                      margin: 0,
                      fontFamily: "inherit",
                      fontSize: "14px"
                    }}>
                      {report.content}
                    </pre>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Reports;
