import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom"; // ✅ You need this import!
import { Calendar, dateFnsLocalizer } from "react-big-calendar";
import format from "date-fns/format";
import parse from "date-fns/parse";
import startOfWeek from "date-fns/startOfWeek";
import getDay from "date-fns/getDay";
import "react-big-calendar/lib/css/react-big-calendar.css";

const locales = {
  "en-US": require("date-fns/locale/en-US")
};

const localizer = dateFnsLocalizer({
  format,
  parse,
  startOfWeek: () => startOfWeek(new Date(), { weekStartsOn: 1 }),
  getDay,
  locales
});

const CalendarPage = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchCalendarData = async () => {
      try {
        setLoading(true);
        const [casesResponse, tasksResponse] = await Promise.all([
          fetch('http://localhost:5000/cases'),
          fetch('http://localhost:5000/tasks/advocate/advocate1') // Using advocate1 from database
        ]);

        if (!casesResponse.ok || !tasksResponse.ok) {
          throw new Error('Failed to fetch calendar data');
        }

        const cases = await casesResponse.json();
        const tasks = await tasksResponse.json();

        const calendarEvents = [];

        // Add court hearings from cases
        cases.forEach(caseItem => {
          if (caseItem.nextHearing && caseItem.nextHearing !== '-') {
            const hearingDate = new Date(caseItem.nextHearing);
            if (!isNaN(hearingDate.getTime())) {
              calendarEvents.push({
                id: `hearing-${caseItem.id}`,
                title: `🏛️ Court Hearing - ${caseItem.title}`,
                start: hearingDate,
                end: new Date(hearingDate.getTime() + 2 * 60 * 60 * 1000), // 2 hours duration
                resource: {
                  type: 'court',
                  caseId: caseItem.id,
                  client: caseItem.client
                }
              });
            }
          }
        });

        // Add task deadlines
        tasks.forEach(task => {
          if (task.end_date) {
            const deadlineDate = new Date(task.end_date);
            if (!isNaN(deadlineDate.getTime())) {
              calendarEvents.push({
                id: `task-${task.id}`,
                title: `📋 Task Deadline - ${task.title}`,
                start: deadlineDate,
                end: new Date(deadlineDate.getTime() + 1 * 60 * 60 * 1000), // 1 hour duration
                resource: {
                  type: 'task',
                  taskId: task.id,
                  staff: task.staff_name,
                  client: task.client_name
                }
              });
            }
          }
        });

        // Add some sample client meetings and reminders
        const sampleEvents = [
          {
            id: 'meeting-1',
            title: '👥 Client Meeting - John Doe',
            start: new Date(2025, 9, 25, 14, 0),
            end: new Date(2025, 9, 25, 15, 30),
            resource: { type: 'meeting' }
          },
          {
            id: 'reminder-1',
            title: '🔔 Reminder - File documents',
            start: new Date(2025, 9, 28, 9, 0),
            end: new Date(2025, 9, 28, 9, 30),
            resource: { type: 'reminder' }
          },
          {
            id: 'staff-1',
            title: '👤 Staff Available - Staff Member 1',
            start: new Date(2025, 9, 30, 10, 0),
            end: new Date(2025, 9, 30, 17, 0),
            resource: { type: 'staff' }
          }
        ];

        setEvents([...calendarEvents, ...sampleEvents]);
      } catch (err) {
        console.error('Error fetching calendar data:', err);
        setError(err.message);
        // Fallback to sample data
        setEvents([
          {
            id: 'fallback-1',
            title: "🏛️ Court Hearing - John Doe",
            start: new Date(2025, 9, 20, 10, 0),
            end: new Date(2025, 9, 20, 12, 0),
            resource: { type: 'court' }
          }
        ]);
      } finally {
        setLoading(false);
      }
    };

    fetchCalendarData();
  }, []);

  const handleSelectSlot = (slotInfo) => {
    const title = prompt("Enter Event Title:");
    if (title) {
      setEvents([
        ...events,
        {
          id: `manual-${Date.now()}`,
          title,
          start: slotInfo.start,
          end: slotInfo.end,
          resource: { type: 'manual' }
        }
      ]);
    }
  };

  // Custom event styling based on type
  const eventStyleGetter = (event) => {
    let backgroundColor = '#3174ad'; // default blue

    switch (event.resource?.type) {
      case 'court':
        backgroundColor = '#6f42c1'; // purple for court hearings/hearing dates
        break;
      case 'meeting':
        backgroundColor = '#007bff'; // blue for client meetings
        break;
      case 'task':
        backgroundColor = '#fd7e14'; // orange for task deadlines
        break;
      case 'staff':
        backgroundColor = '#28a745'; // green for staff availability
        break;
      case 'reminder':
        backgroundColor = '#ffc107'; // yellow for reminders
        break;
      default:
        backgroundColor = '#6c757d'; // gray for manual/other events
    }

    return {
      style: {
        backgroundColor,
        borderRadius: '5px',
        opacity: 0.8,
        color: 'white',
        border: '0px',
        display: 'block'
      }
    };
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        padding: "30px",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif"
      }}
    >
      {/* Header */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          background: "burlywood",
          padding: "20px 30px",
          borderRadius: "15px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
          marginBottom: "30px"
        }}
      >
        <h2 style={{ color: "#333", fontSize: "1.8rem", margin: 0 }}>
          📅 Case Calendar
        </h2>

        <Link
          to="/dashboard"
          className="back-button"
          aria-label="Back to Dashboard"
          style={{
            display: "inline-block",
            background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
            color: "white",
            padding: "10px 20px",
            borderRadius: "8px",
            fontWeight: "bold",
            textDecoration: "none",
            boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
            transition: "0.3s ease"
          }}
          onMouseEnter={(e) => (e.target.style.transform = "translateY(-3px)")}
          onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
        >
          ⬅️ Back to Dashboard
        </Link>
      </div>

      {/* Calendar */}
      <div
        style={{
          background: "white",
          borderRadius: "15px",
          padding: "20px",
          boxShadow: "0 8px 25px rgba(0,0,0,0.1)"
        }}
      >
        {loading && (
          <div style={{ textAlign: "center", padding: "50px", fontSize: "1.2rem", color: "#666" }}>
            Loading calendar events...
          </div>
        )}
        {error && (
          <div style={{ textAlign: "center", padding: "20px", color: "red", fontSize: "1.1rem" }}>
            Error loading calendar data: {error}. Showing fallback data.
          </div>
        )}
        {!loading && (
          <Calendar
            localizer={localizer}
            events={events}
            startAccessor="start"
            endAccessor="end"
            selectable
            onSelectSlot={handleSelectSlot}
            eventPropGetter={eventStyleGetter}
            style={{ height: 500 }}
          />
        )}
      </div>
    </div>
  );
};

export default CalendarPage;
