import React, { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
import "./Cases.css";

const CaseDetail = () => {
  const { id } = useParams();
  const [caseData, setCaseData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Case files states
  const [caseFiles, setCaseFiles] = useState([]);
  const [filesLoading, setFilesLoading] = useState(false);
  const [uploadLoading, setUploadLoading] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [userRole, setUserRole] = useState("");

  // Shared document upload states
  const [showSharedUpload, setShowSharedUpload] = useState(false);
  const [sharedFile, setSharedFile] = useState(null);
  const [selectedCases, setSelectedCases] = useState([]);
  const [availableCases, setAvailableCases] = useState([]);
  const [sharedUploadLoading, setSharedUploadLoading] = useState(false);
  const [casesLoading, setCasesLoading] = useState(false);



  useEffect(() => {
    const fetchCaseDetail = async () => {
      try {
        const userRole = localStorage.getItem("role");
        const username = localStorage.getItem("username");

        // If user is staff, check if the case is assigned to them
        if (userRole === "staff" && username) {
          const assignedCasesResponse = await fetch(`http://localhost:5000/cases/staff/${username}`);
          if (!assignedCasesResponse.ok) {
            throw new Error("Failed to verify case assignment");
          }
          const assignedCases = await assignedCasesResponse.json();
          const isAssigned = assignedCases.some(caseItem => caseItem.id === parseInt(id));

          if (!isAssigned) {
            throw new Error("You do not have permission to view this case. It is not assigned to you.");
          }
        }

        const response = await fetch(`http://localhost:5000/cases/${id}`);
        if (!response.ok) {
          throw new Error("Failed to fetch case details");
        }
        const data = await response.json();
        setCaseData(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchCaseDetail();
  }, [id]);

  useEffect(() => {
    const role = localStorage.getItem("role");
    setUserRole(role);
    fetchCaseFiles();
  }, [id]);

  const fetchCaseFiles = async () => {
    setFilesLoading(true);
    try {
      const response = await fetch(`http://localhost:5000/cases/${id}/files`);
      if (!response.ok) {
        throw new Error("Failed to fetch case files");
      }
      const data = await response.json();
      setCaseFiles(Array.isArray(data.files) ? data.files : []);
    } catch (err) {
      console.error("Error fetching files:", err);
      setCaseFiles([]);
    } finally {
      setFilesLoading(false);
    }
  };

  const handleFileUpload = async () => {
    if (!selectedFile) return;

    setUploadLoading(true);
    const formData = new FormData();
    formData.append("files", selectedFile);
    formData.append(
      "uploadedBy",
      localStorage.getItem("username") || "Unknown"
    );

    try {
      const response = await fetch(`http://localhost:5000/cases/${id}/files`, {
        method: "POST",
        body: formData,
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.message || `Upload failed with status ${response.status}`);
      }

      alert("File uploaded successfully!");
      setSelectedFile(null);
      fetchCaseFiles();
    } catch (err) {
      console.error("Upload error:", err);
      alert(`File upload failed: ${err.message}`);
    } finally {
      setUploadLoading(false);
    }
  };

  const handleFileDownload = async (fileId, fileName) => {
    try {
      const response = await fetch(
        `http://localhost:5000/files/${fileId}/download`
      );
      if (!response.ok) {
        throw new Error("Failed to download file");
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      console.error(err);
      alert("Download failed");
    }
  };

  const handleFileDelete = async (fileId, fileName) => {
    if (!window.confirm(`Delete "${fileName}" permanently?`)) return;

    try {
      const response = await fetch(
        `http://localhost:5000/files/${fileId}`,
        { method: "DELETE" }
      );

      if (!response.ok) {
        throw new Error("Failed to delete file");
      }

      alert("File deleted successfully!");
      fetchCaseFiles();
    } catch (err) {
      console.error(err);
      alert("Delete failed");
    }
  };



  if (loading) return <div className="loading">Loading case details...</div>;
  if (error) return <div className="error">Error: {error}</div>;
  if (!caseData) return <div className="no-data">Case not found.</div>;

  return (
    <div className="case-detail-container">
      <header className="cases-header sticky-header">
        <div className="back-button-wrapper">
          <Link
            to={
              userRole === "client"
                ? "/client-cases"
                : userRole === "staff"
                ? "/staff-dashboard"
                : "/cases"
            }
            className="back-button"
          >
            ⬅️ Back
          </Link>
        </div>
        <div className="cases-header-info">
          <h1>📄 Case Details</h1>
          <p>View detailed information for this case</p>
        </div>
      </header>

      <main className="case-detail-main">
        <div className="case-detail-card">
          <h2>{caseData.title}</h2>

          <div className="case-detail-info">
            <p><strong>ID:</strong> {caseData.id}</p>
            <p><strong>Case Title:</strong> {caseData.title}</p>
            <p><strong>Case Type:</strong> {caseData.case_type || "Not specified"}</p>
            {caseData.case_type !== "Civil" && <p><strong>FIR Number:</strong> {caseData.fir_number || "Not specified"}</p>}
            <p><strong>Court Name:</strong> {caseData.court_name || "Not specified"}</p>
            <p><strong>Accused Name:</strong> {caseData.accused_name || "Not specified"}</p>
            {caseData.case_type !== "Civil" && <p><strong>IPC Sections:</strong> {caseData.ipc_sections || "Not specified"}</p>}
            {caseData.case_type === "Civil" && <p><strong>Original Suit:</strong> {caseData.original_suit || "Not specified"}</p>}
            <p><strong>Client:</strong> {caseData.client}</p>
            <p>
              <strong>Status:</strong>{" "}
              <span className={`status-badge ${caseData.status.toLowerCase()}`}>
                {caseData.status}
              </span>
            </p>
            <p><strong>Next Hearing Date:</strong> {caseData.nextHearing}</p>
          </div>

          {/* Case Files Section */}
          <div className="case-files-section">
            <h3>📎 Case Files</h3>

            {userRole === "advocate" && (
              <div className="file-upload-container">
                <input
                  type="file"
                  onChange={(e) => setSelectedFile(e.target.files[0])}
                />
                <button
                  onClick={handleFileUpload}
                  disabled={!selectedFile || uploadLoading}
                  className="upload-btn"
                >
                  {uploadLoading ? "Uploading..." : "Upload File"}
                </button>
              </div>
            )}

            {filesLoading ? (
              <p>Loading files...</p>
            ) : caseFiles.length === 0 ? (
              <p>No files uploaded for this case.</p>
            ) : (
              <div className="file-list">
                {caseFiles.map((file) => (
                  <div key={file.id} className="file-item">
                    <span>{file.original_name}</span>
                    <button
                      onClick={() =>
                        handleFileDownload(file.id, file.original_name)
                      }
                    >
                      📥 Download
                    </button>
                    {userRole === "advocate" && (
                      <button
                        onClick={() =>
                          handleFileDelete(file.id, file.original_name)
                        }
                      >
                        🗑️ Delete
                      </button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>


        </div>
      </main>
    </div>
  );
};

export default CaseDetail;
