import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import ssImage from '../assets/AA.png';

const Billing = () => {
  const [invoices, setInvoices] = useState([]);
  const [clients, setClients] = useState([]);
  const [cases, setCases] = useState([]);
  const [staff, setStaff] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingInvoice, setEditingInvoice] = useState(null);

  const [form, setForm] = useState({
    client: "",
    client_id: "",
    case_id: "",
    case_description: "",
    staff_handling: "",
    amount_to_pay: "",
    amount_paid: "",
    dueDate: ""
  });

  const [editForm, setEditForm] = useState({
    amount_to_pay: "",
    amount_paid: "",
    status: "",
    dueDate: ""
  });

  /* ---------------- FETCH DATA ---------------- */
  useEffect(() => {
    const advocateUsername = localStorage.getItem("username");

    fetch("http://localhost:5000/invoices")
      .then(res => res.json())
      .then(setInvoices);

    fetch("http://localhost:5000/clients")
      .then(res => res.json())
      .then(setClients);

    fetch("http://localhost:5000/cases")
      .then(res => res.json())
      .then(setCases);

    if (advocateUsername) {
      fetch(`http://localhost:5000/staff/${advocateUsername}`)
        .then(res => res.json())
        .then(data => setStaff(Array.isArray(data) ? data : []))
        .catch(() => setStaff([]));
    }
  }, []);

  /* ---------------- ADD INVOICE ---------------- */
  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validate required fields
    if (!form.client_id) {
      alert("Please select a client");
      return;
    }
    if (!form.case_id) {
      alert("Please select a case");
      return;
    }

    const amountToPay = Number(form.amount_to_pay);
    const amountPaid = Number(form.amount_paid);

    if (isNaN(amountToPay) || amountToPay <= 0) {
      alert("Please enter a valid amount to pay greater than 0");
      return;
    }

    if (isNaN(amountPaid) || amountPaid < 0) {
      alert("Please enter a valid amount paid (0 or greater)");
      return;
    }

    if (amountPaid > amountToPay) {
      alert("Amount paid cannot exceed amount to pay");
      return;
    }

    const payload = {
      client: form.client,
      client_id: form.client_id,
      case_id: form.case_id,
      case_description: form.case_description,
      staff_handling: form.staff_handling,
      amount: amountToPay, // Total amount
      amount_to_pay: amountToPay,
      amount_paid: amountPaid,
      status: "Pending", // Default status
      dueDate: form.dueDate
    };

    const res = await fetch("http://localhost:5000/invoices", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      try {
        const errorData = await res.json();
        alert("Failed to save invoice: " + (errorData.message || "Unknown error"));
      } catch (e) {
        alert("Failed to save invoice: Server returned an error (check console for details)");
        console.error("Failed to parse error response:", e);
      }
      return;
    }

    const updated = await fetch("http://localhost:5000/invoices");
    setInvoices(await updated.json());

    setForm({
      client: "",
      client_id: "",
      case_id: "",
      case_description: "",
      staff_handling: "",
      amount_to_pay: "",
      amount_paid: "",
      dueDate: ""
    });

    setShowForm(false);
  };

  /* ---------------- EDIT INVOICE ---------------- */
  const handleEdit = (invoice) => {
    setEditingInvoice(invoice.id);
    setEditForm({
      amount_to_pay: invoice.amount_to_pay,
      amount_paid: invoice.amount_paid,
      status: invoice.status,
      dueDate: invoice.dueDate ? invoice.dueDate.split('T')[0] : ''
    });
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();

    const amountToPay = Number(editForm.amount_to_pay);
    const amountPaid = Number(editForm.amount_paid);

    if (amountPaid > amountToPay) {
      alert("Amount paid cannot exceed amount to pay");
      return;
    }

    // Always send the current form values
    const payload = {
      amount_to_pay: editForm.amount_to_pay,
      amount_paid: editForm.amount_paid,
      status: editForm.status,
      dueDate: editForm.dueDate
    };

    const res = await fetch(`http://localhost:5000/invoices/${editingInvoice}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      alert("Failed to update invoice");
      return;
    }

    const updated = await fetch("http://localhost:5000/invoices");
    setInvoices(await updated.json());

    setEditingInvoice(null);
    setEditForm({
      amount_to_pay: "",
      amount_paid: "",
      status: "",
      dueDate: ""
    });
  };

  const cancelEdit = () => {
    setEditingInvoice(null);
    setEditForm({
      amount_to_pay: "",
      amount_paid: "",
      status: "",
      dueDate: ""
    });
  };

  /* ---------------- UI ---------------- */
  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif" }}>

      {/* MAIN CONTENT */}
      <div style={{ flex: 1, padding: "40px" }}>

        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
          <Link to="/dashboard">
            <button
              style={{
                padding: "10px 20px",
                borderRadius: "20px",
                border: "none",
                background: "linear-gradient(135deg,#6c757d,#495057)",
                color: "white",
                fontSize: "0.9rem",
                cursor: "pointer",
                boxShadow: "0 4px 15px rgba(0,0,0,0.2)"
              }}
            >
              ← Back to Dashboard
            </button>
          </Link>

          <h2 style={{
            textAlign: "center",
            fontSize: "2.2rem",
            margin: 0,
            flex: 1,
            color: "white"
          }}>
            💰 Billing
          </h2>

          <div style={{ width: "140px" }}></div> {/* Spacer for centering */}
        </div>

        <div style={{ textAlign: "center", marginBottom: "30px" }}>
          <button
            onClick={() => setShowForm(!showForm)}
            style={{
              padding: "12px 25px",
              borderRadius: "30px",
              border: "none",
              background: showForm
                ? "linear-gradient(135deg,#dc3545,#b02a37)"
                : "linear-gradient(135deg,#28a745,#20c997)",
              color: "white",
              fontSize: "1rem",
              cursor: "pointer",
              boxShadow: "0 8px 20px rgba(0,0,0,0.2)"
            }}
          >
            {showForm ? "Cancel" : "➕ Add Billing"}
          </button>
        </div>

        {/* ADD INVOICE CARD */}
        {showForm && (
          <div style={{
            maxWidth: "900px",
            margin: "0 auto 40px",
            background: "white",
            borderRadius: "20px",
            padding: "30px",
            boxShadow: "0 20px 40px rgba(0,0,0,0.15)"
          }}>
            <h3 style={{ textAlign: "center", marginBottom: "20px" }}>
              📝 Create billing
            </h3>

            <form onSubmit={handleSubmit}
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(250px,1fr))",
                gap: "20px"
              }}
            >

              <select required onChange={(e) => {
                const c = clients.find(x => x.id == e.target.value);
                if (c) {
                  setForm({ ...form, client_id: c.id, client: c.name });
                }
              }}>
                <option value="">Select Client</option>
                {clients.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>

              <select required onChange={(e) => {
                const cs = cases.find(x => x.id == e.target.value);
                if (cs) {
                  setForm({ ...form, case_id: cs.id, case_description: cs.title });
                }
              }}>
                <option value="">Select Case</option>
                {cases.map(cs => (
                  <option key={cs.id} value={cs.id}>{cs.title}</option>
                ))}
              </select>

              <select onChange={(e) =>
                setForm({ ...form, staff_handling: e.target.value })
              }>
                <option value="">Select Staff (Optional)</option>
                {staff.map(s => (
                  <option key={s.id} value={s.name}>{s.name}</option>
                ))}
              </select>

              <input type="number" placeholder="Amount to Pay" min="1" step="0.01" required
                onChange={e => setForm({ ...form, amount_to_pay: e.target.value })} />

              <input type="number" placeholder="Amount Paid" min="0" step="0.01" required
                onChange={e => setForm({ ...form, amount_paid: e.target.value })} />

              <input type="date" required
                onChange={e => setForm({ ...form, dueDate: e.target.value })} />

              <button type="submit"
                style={{
                  gridColumn: "1/-1",
                  padding: "14px",
                  borderRadius: "30px",
                  border: "none",
                  background: "linear-gradient(135deg,#667eea,#764ba2)",
                  color: "white",
                  fontSize: "1rem",
                  cursor: "pointer"
                }}>
                💾 Save billing
              </button>
            </form>
          </div>
        )}

        {/* INVOICE CARDS */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill,minmax(320px,1fr))",
          gap: "25px"
        }}>
          {invoices.map(i => (
            <div key={i.id} style={{
              background: "linear-gradient(135deg,#a8edea,#fed6e3)",
              borderRadius: "20px",
              padding: "20px",
              boxShadow: "0 10px 25px rgba(0,0,0,0.15)"
            }}>
              {editingInvoice === i.id ? (
                // EDIT FORM
                <form onSubmit={handleEditSubmit}>
                  <h4>Edit Billing</h4>
                  <div style={{ marginBottom: "10px" }}>
                    <label><b>Amount to Pay:</b></label>
                    <input
                      type="number"
                      value={editForm.amount_to_pay}
                      onChange={e => setEditForm({...editForm, amount_to_pay: e.target.value})}
                      style={{ width: "100%", padding: "5px", marginTop: "5px" }}
                    />
                  </div>
                  <div style={{ marginBottom: "10px" }}>
                    <label><b>Amount Paid:</b></label>
                    <input
                      type="number"
                      value={editForm.amount_paid}
                      onChange={e => setEditForm({...editForm, amount_paid: e.target.value})}
                      style={{ width: "100%", padding: "5px", marginTop: "5px" }}
                    />
                  </div>
                  <div style={{ marginBottom: "10px" }}>
                    <label><b>Status:</b></label>
                    <select
                      value={editForm.status}
                      onChange={e => {
                        const newStatus = e.target.value;
                        const updatedForm = { ...editForm, status: newStatus };
                        // If status is changed to "Paid", automatically set amount_paid to amount_to_pay
                        if (newStatus === "Paid") {
                          updatedForm.amount_paid = editForm.amount_to_pay;
                        }
                        setEditForm(updatedForm);
                      }}
                      style={{ width: "100%", padding: "5px", marginTop: "5px" }}
                    >
                      <option value="Pending">Pending</option>
                      <option value="Paid">Paid</option>
                      <option value="Overdue">Overdue</option>
                    </select>
                  </div>
                  <div style={{ marginBottom: "15px" }}>
                    <label><b>Due Date:</b></label>
                    <input
                      type="date"
                      value={editForm.dueDate ? editForm.dueDate.split('T')[0] : ''}
                      onChange={e => setEditForm({...editForm, dueDate: e.target.value})}
                      style={{ width: "100%", padding: "5px", marginTop: "5px" }}
                    />
                  </div>
                  <div style={{ display: "flex", gap: "10px" }}>
                    <button type="submit" style={{
                      flex: 1,
                      padding: "8px",
                      background: "linear-gradient(135deg,#28a745,#20c997)",
                      color: "white",
                      border: "none",
                      borderRadius: "5px",
                      cursor: "pointer"
                    }}>
                      💾 Save
                    </button>
                    <button type="button" onClick={cancelEdit} style={{
                      flex: 1,
                      padding: "8px",
                      background: "linear-gradient(135deg,#dc3545,#b02a37)",
                      color: "white",
                      border: "none",
                      borderRadius: "5px",
                      cursor: "pointer"
                    }}>
                      ❌ Cancel
                    </button>
                  </div>
                </form>
              ) : (
                // DISPLAY MODE
                <>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
                    <h4>Billing</h4>
                    <button
                      onClick={() => handleEdit(i)}
                      style={{
                        padding: "5px 10px",
                        background: "linear-gradient(135deg,#007bff,#0056b3)",
                        color: "white",
                        border: "none",
                        borderRadius: "5px",
                        cursor: "pointer",
                        fontSize: "0.8rem"
                      }}
                    >
                      ✏️ Edit
                    </button>
                  </div>
                  <p><b>Client:</b> {i.client}</p>
                  <p><b>Case:</b> {i.case_description}</p>
                  <p><b>Staff:</b> {i.staff_handling}</p>
                  <p><b>Amount:</b> ₹{i.amount_to_pay}</p>
                  <p><b>Paid:</b> ₹{i.amount_paid}</p>
                  <p><b>Remaining:</b> ₹{i.remaining_amount}</p>
                  <p><b>Status:</b> {i.status}</p>
                  <p><b>Due:</b> {i.dueDate ? new Date(i.dueDate).toLocaleDateString() : 'N/A'}</p>
                </>
              )}
            </div>
          ))}
        </div>

      </div>
    </div>
  );
};

export default Billing;
