import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import io from "socket.io-client";

const Communication = () => {
  const [search, setSearch] = useState("");
  const [messagesData, setMessagesData] = useState([]);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const response = await fetch("http://localhost:5000/messages");
        if (!response.ok) {
          throw new Error("Failed to fetch messages");
        }
        const data = await response.json();
        setMessagesData(data);
      } catch (err) {
        console.error("Error fetching messages:", err);
      }
    };

    fetchMessages();
  }, []);

  useEffect(() => {
    // Initialize Socket.IO connection
    const newSocket = io("http://localhost:5000");
    setSocket(newSocket);

    // Listen for new messages
    newSocket.on("newMessage", (message) => {
      setMessagesData((prevMessages) => [message, ...prevMessages]);
    });

    // Cleanup on unmount
    return () => {
      newSocket.disconnect();
    };
  }, []);

  const filteredMessages = messagesData.filter(
    (m) =>
      m.sender.toLowerCase().includes(search.toLowerCase()) ||
      m.subject.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div
      style={{
        minHeight: "100vh",
        padding: "30px",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      }}
    >
      {/* Header */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          background: "burlywood",
          padding: "20px 30px",
          borderRadius: "15px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
          marginBottom: "30px",
        }}
      >
        <h2 style={{ color: "#333", fontSize: "1.8rem", margin: 0 }}>💬 Communication Hub</h2>

        <Link
          to="/dashboard"
          style={{
            display: "inline-block",
            background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
            color: "white",
            padding: "10px 20px",
            borderRadius: "8px",
            fontWeight: "bold",
            textDecoration: "none",
            boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
            transition: "0.3s ease",
          }}
          onMouseEnter={(e) => (e.target.style.transform = "translateY(-3px)")}
          onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
        >
          ⬅️ Back to Dashboard
        </Link>
      </div>

      {/* Search */}
      <div
        style={{
          background: "white",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
          marginBottom: "25px",
        }}
      >
        <input
          type="search"
          placeholder="🔍 Search by sender or subject..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{
            width: "100%",
            padding: "12px",
            borderRadius: "8px",
            border: "1px solid #ccc",
            fontSize: "1rem",
          }}
        />
      </div>

      {/* Compose Message */}
      <div
        style={{
          background: "white",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
          marginBottom: "25px",
        }}
      >
        <h3 style={{ marginTop: 0, color: "#333" }}>📝 Compose New Message</h3>
        <form onSubmit={(e) => {
          e.preventDefault();
          const formData = new FormData(e.target);
          const message = {
            id: Date.now(), // Simple ID generation
            sender: formData.get("sender"),
            subject: formData.get("subject"),
            content: formData.get("content"),
            date: new Date().toLocaleDateString(),
            preview: formData.get("content").substring(0, 50) + "...",
          };
          socket.emit("sendMessage", message);
          e.target.reset();
        }}>
          <div style={{ marginBottom: "15px" }}>
            <input
              type="text"
              name="sender"
              placeholder="Your Name"
              required
              style={{
                width: "100%",
                padding: "10px",
                borderRadius: "5px",
                border: "1px solid #ccc",
                fontSize: "1rem",
                marginBottom: "10px",
              }}
            />
            <input
              type="text"
              name="subject"
              placeholder="Subject"
              required
              style={{
                width: "100%",
                padding: "10px",
                borderRadius: "5px",
                border: "1px solid #ccc",
                fontSize: "1rem",
                marginBottom: "10px",
              }}
            />
            <textarea
              name="content"
              placeholder="Message content..."
              required
              rows="4"
              style={{
                width: "100%",
                padding: "10px",
                borderRadius: "5px",
                border: "1px solid #ccc",
                fontSize: "1rem",
                resize: "vertical",
              }}
            />
          </div>
          <button
            type="submit"
            style={{
              background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
              color: "white",
              padding: "10px 20px",
              border: "none",
              borderRadius: "5px",
              fontSize: "1rem",
              cursor: "pointer",
              fontWeight: "bold",
            }}
          >
            Send Message
          </button>
        </form>
      </div>



      {/* Messages List */}
      <div
        style={{
          background: "white",
          borderRadius: "15px",
          padding: "20px",
          boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
        }}
      >
        {filteredMessages.length === 0 ? (
          <p style={{ textAlign: "center", color: "#777" }}>No messages found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
            {filteredMessages.map((message) => (
              <div
                key={message.id}
                style={{
                  background: "linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)",
                  padding: "15px",
                  borderRadius: "10px",
                  boxShadow: "0 2px 5px rgba(0,0,0,0.1)",
                  transition: "0.3s ease",
                }}
                onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
                onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
                  <h4 style={{ margin: 0, color: "#333" }}>{message.subject}</h4>
                  <span style={{ fontSize: "0.9rem", color: "#666" }}>{message.date}</span>
                </div>
                <p style={{ margin: "5px 0", color: "#666" }}>From: {message.sender}</p>
                <p style={{ margin: "5px 0", color: "#555" }}>{message.preview}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Communication;
