import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";

const ClientCommunication = () => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [newMessage, setNewMessage] = useState("");

  useEffect(() => {
    fetchMessages();
  }, []);

  const fetchMessages = async () => {
    try {
      const response = await fetch("http://localhost:5000/messages");
      if (!response.ok) {
        throw new Error("Failed to fetch messages");
      }
      const data = await response.json();
      // Filter messages for the logged-in client
      const clientName = localStorage.getItem("clientName") || "John Doe"; // Default for demo
      const clientMessages = data.filter(message => message.sender === clientName || message.sender === "Advocate");
      setMessages(clientMessages);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const sendMessage = () => {
    if (newMessage.trim()) {
      // In a real app, this would send to backend
      const message = {
        id: messages.length + 1,
        sender: localStorage.getItem("clientName") || "John Doe",
        subject: "New Message",
        preview: newMessage,
        date: new Date().toISOString().split('T')[0]
      };
      setMessages([...messages, message]);
      setNewMessage("");
    }
  };

  if (loading) return <div>Loading messages...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div style={{ padding: "20px", background: "linear-gradient(135deg, #DEB887 0%, #A0522D 100%)", minHeight: "100vh" }}>
      <div style={{ marginBottom: "20px" }}>
        <Link to="/client-dashboard">
          <button
            style={{
              padding: "10px 20px",
              background: "linear-gradient(135deg, #28a745 0%, #20c997 100%)",
              color: "white",
              border: "none",
              borderRadius: "8px",
              fontSize: "14px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            ← Back to Dashboard
          </button>
        </Link>
      </div>
      <h2>Communication</h2>
      <div style={{ marginBottom: "20px" }}>
        <textarea
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type your message here..."
          style={{ width: "100%", height: "100px", padding: "10px" }}
        />
        <button onClick={sendMessage} style={{ marginTop: "10px", padding: "10px 20px" }}>
          Send Message
        </button>
      </div>
      <h3>Message History</h3>
      {messages.length === 0 ? (
        <p>No messages found.</p>
      ) : (
        <ul style={{ listStyleType: "none", padding: 0 }}>
          {messages.map((message) => (
            <li key={message.id} style={{ border: "1px solid #ddd", padding: "10px", marginBottom: "10px" }}>
              <strong>{message.sender}:</strong> {message.preview} <em>({message.date})</em>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default ClientCommunication;
