import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Cases.css";

const Cases = () => {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [casesData, setCasesData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [documentCounts, setDocumentCounts] = useState({});
  const [historyDocumentCounts, setHistoryDocumentCounts] = useState({});
  const [editingCase, setEditingCase] = useState(null);
  const [editForm, setEditForm] = useState({
    title: '',
    case_type: '',
    fir_number: '',
    court_name: '',
    accused_name: '',
    ipc_sections: '',
    original_suit: '',
    status: '',
    client: '',
    nextHearing: ''
  });

  useEffect(() => {
    fetchCases();
    fetchDocumentCounts();
  }, []);

  const fetchCases = async () => {
    try {
      const response = await fetch("http://localhost:5000/cases");
      if (!response.ok) {
        throw new Error("Failed to fetch cases");
      }
      const data = await response.json();
      console.log("Fetched cases data:", data);
      setCasesData(data);
    } catch (err) {
      console.error("Error fetching cases:", err);
    }
  };

  const fetchDocumentCounts = async () => {
    try {
      const [docResponse, historyDocResponse] = await Promise.all([
        fetch("http://localhost:5000/cases/document-counts"),
        fetch("http://localhost:5000/cases/history-document-counts")
      ]);

      if (docResponse.ok) {
        const docData = await docResponse.json();
        const docMap = {};
        docData.forEach(item => {
          docMap[item.case_id] = item.document_count;
        });
        setDocumentCounts(docMap);
      }

      if (historyDocResponse.ok) {
        const historyDocData = await historyDocResponse.json();
        const historyDocMap = {};
        historyDocData.forEach(item => {
          historyDocMap[item.case_id] = item.history_document_count;
        });
        setHistoryDocumentCounts(historyDocMap);
      }
    } catch (err) {
      console.error("Error fetching document counts:", err);
    }
  };

  const deleteCase = async (caseId) => {
    if (!window.confirm("Are you sure you want to delete this case? This action cannot be undone.")) {
      return;
    }

    setLoading(true);
    try {
      const advocateUsername = localStorage.getItem('username');
      const role = localStorage.getItem('role');

      console.log('Delete case attempt:', { caseId, advocateUsername, role });

      if (!advocateUsername) {
        alert("You must be logged in as an advocate to delete cases.");
        return;
      }

      if (role !== 'advocate') {
        alert("Only advocates can delete cases.");
        return;
      }

      const response = await fetch(`http://localhost:5000/cases/${caseId}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ advocateUsername }),
      });

      const result = await response.json();
      console.log('Delete case response:', result);

      if (result.success) {
        alert("Case deleted successfully!");
        // Refresh the cases list
        fetchCases();
      } else {
        alert(`Failed to delete case: ${result.message}`);
      }
    } catch (error) {
      console.error("Error deleting case:", error);
      alert(`An error occurred while deleting the case: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Group cases by title to identify similar cases
  const groupedCases = casesData.reduce((acc, caseItem) => {
    const title = caseItem.title || '';
    if (!acc[title]) {
      acc[title] = [];
    }
    acc[title].push(caseItem);
    return acc;
  }, {});

  const filteredCases = casesData.filter(
    (c) =>
      (c.title && c.title.toLowerCase().includes(search.toLowerCase())) ||
      (c.client && c.client.toLowerCase().includes(search.toLowerCase()))
  );

  // Get document count for a case
  const getDocumentCount = (caseId) => {
    return documentCounts[caseId] || 0;
  };

  // Get history document count for a case
  const getHistoryDocumentCount = (caseId) => {
    return historyDocumentCounts[caseId] || 0;
  };

  // Check if case title has multiple cases (similar cases)
  const isSimilarCase = (caseTitle) => {
    return groupedCases[caseTitle]?.length > 1;
  };

  // Format FIR number to display as number/year format
  const formatFIRNumber = (firNumber) => {
    if (!firNumber || firNumber === '-') return '-';
    // If it's already in format like "123/2024", return as is
    if (firNumber.includes('/')) return firNumber;
    // Otherwise, format as number/2024
    return `${firNumber}/2024`;
  };

  // Start editing a case
  const startEditing = (caseItem) => {
    setEditingCase(caseItem.id);
    setEditForm({
      title: caseItem.title || '',
      case_type: caseItem.case_type || '',
      fir_number: caseItem.fir_number || '',
      court_name: caseItem.court_name || '',
      accused_name: caseItem.accused_name || '',
      ipc_sections: caseItem.ipc_sections || '',
      original_suit: caseItem.original_suit || '',
      status: caseItem.status || 'Open',
      client: caseItem.client || '',
      nextHearing: caseItem.nextHearing ? new Date(caseItem.nextHearing).toISOString().slice(0, 16) : ''
    });
  };

  // Cancel editing
  const cancelEditing = () => {
    setEditingCase(null);
    setEditForm({
      title: '',
      case_type: '',
      fir_number: '',
      court_name: '',
      accused_name: '',
      ipc_sections: '',
      original_suit: '',
      status: '',
      client: '',
      nextHearing: ''
    });
  };

  // Save case changes
  const saveCase = async () => {
    if (!editingCase) return;

    setLoading(true);
    try {
      const response = await fetch(`http://localhost:5000/cases/${editingCase}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(editForm),
      });

      const result = await response.json();
      console.log('Update case response:', result);

      if (result.success) {
        alert("Case updated successfully!");
        setEditingCase(null);
        // Refresh the cases list
        fetchCases();
      } else {
        alert(`Failed to update case: ${result.message}`);
      }
    } catch (error) {
      console.error("Error updating case:", error);
      alert(`An error occurred while updating the case: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="cases-container">
      <header className="cases-header sticky-header">
        <div className="back-button-wrapper">
          <Link to="/dashboard" className="back-button" aria-label="Back to Dashboard">
  ⬅️ Back to Dashboard
</Link>


        </div>

        <div className="cases-header-info">
          <h1>📂 Case Management</h1>
          <p>Manage your legal cases with ease and style</p>
        </div>

        <div className="cases-header-actions">
          <div className="cases-search">
            <input
              type="search"
              placeholder="🔍 Search by case or client..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              aria-label="Search cases"
            />
          </div>
        </div>
      </header>

      <main>
        {editingCase && (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.5)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            zIndex: 1000
          }}>
            <div style={{
              background: 'white',
              padding: '20px',
              borderRadius: '10px',
              maxWidth: '600px',
              width: '90%',
              maxHeight: '80vh',
              overflowY: 'auto'
            }}>
              <h3>Edit Case</h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '20px' }}>
                <div>
                  <label>Title:</label>
                  <input
                    type="text"
                    value={editForm.title}
                    onChange={(e) => setEditForm({...editForm, title: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                  />
                </div>
                <div>
                  <label>Case Type:</label>
                  <input
                    type="text"
                    value={editForm.case_type}
                    onChange={(e) => setEditForm({...editForm, case_type: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                  />
                </div>
                <div>
                  <label>FIR Number:</label>
                  <input
                    type="text"
                    value={editForm.fir_number}
                    onChange={(e) => setEditForm({...editForm, fir_number: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                    disabled={editForm.case_type === "Civil"}
                  />
                </div>
                <div>
                  <label>Court Name:</label>
                  <input
                    type="text"
                    value={editForm.court_name}
                    onChange={(e) => setEditForm({...editForm, court_name: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                  />
                </div>
                <div>
                  <label>Accused Name:</label>
                  <input
                    type="text"
                    value={editForm.accused_name}
                    onChange={(e) => setEditForm({...editForm, accused_name: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                  />
                </div>
                <div>
                  <label>IPC Sections:</label>
                  <input
                    type="text"
                    value={editForm.ipc_sections}
                    onChange={(e) => setEditForm({...editForm, ipc_sections: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                    disabled={editForm.case_type === "Civil"}
                  />
                </div>
                {editForm.case_type === "Civil" && (
                  <div>
                    <label>Original Suit:</label>
                    <input
                      type="text"
                      value={editForm.original_suit}
                      onChange={(e) => setEditForm({...editForm, original_suit: e.target.value})}
                      style={{ width: '100%', padding: '5px' }}
                    />
                  </div>
                )}
                <div>
                  <label>Status:</label>
                  <select
                    value={editForm.status}
                    onChange={(e) => setEditForm({...editForm, status: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                  >
                    <option value="Open">Open</option>
                    <option value="Closed">Closed</option>
                    <option value="Pending">Pending</option>
                    <option value="In Progress">In Progress</option>
                  </select>
                </div>
                <div>
                  <label>Client:</label>
                  <input
                    type="text"
                    value={editForm.client}
                    onChange={(e) => setEditForm({...editForm, client: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                  />
                </div>
                <div style={{ gridColumn: 'span 2' }}>
                  <label>Next Hearing:</label>
                  <input
                    type="datetime-local"
                    value={editForm.nextHearing}
                    onChange={(e) => setEditForm({...editForm, nextHearing: e.target.value})}
                    style={{ width: '100%', padding: '5px' }}
                  />
                </div>
              </div>
              <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
                <button
                  onClick={cancelEditing}
                  style={{
                    background: '#6c757d',
                    color: 'white',
                    border: 'none',
                    padding: '10px 20px',
                    borderRadius: '5px',
                    cursor: 'pointer'
                  }}
                >
                  Cancel
                </button>
                <button
                  onClick={saveCase}
                  disabled={loading}
                  style={{
                    background: '#28a745',
                    color: 'white',
                    border: 'none',
                    padding: '10px 20px',
                    borderRadius: '5px',
                    cursor: loading ? 'not-allowed' : 'pointer'
                  }}
                >
                  {loading ? 'Saving...' : 'Save Changes'}
                </button>
              </div>
            </div>
          </div>
        )}

        <p>Total cases: {casesData.length}, Filtered: {filteredCases.length}</p>
        <table className="cases-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Case Title</th>
              <th>Case Type</th>
              <th>FIR Number</th>
              <th>Court Name</th>
              <th>Accused Name</th>
              <th>IPC Sections</th>
              <th>Original Suit</th>
              <th>Client</th>
              <th>Status</th>
              <th>Next Hearing</th>
              <th>Documents</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredCases.length > 0 ? (
              filteredCases.map((caseItem, index) => {
                const docCount = getDocumentCount(caseItem.id);
                const historyDocCount = getHistoryDocumentCount(caseItem.id);
                const isSimilar = isSimilarCase(caseItem.title);

                return (
                  <tr
                    key={caseItem.id}
                    style={{
                      backgroundColor: isSimilar ? '#fff3cd' : 'transparent',
                      borderLeft: isSimilar ? '4px solid #ffc107' : 'none'
                    }}
                  >
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.id}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                        {caseItem.title}
                        {isSimilar && <span style={{ color: '#856404', fontSize: '0.8em' }}>🔄 Similar</span>}
                      </div>
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.case_type || '-'}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {formatFIRNumber(caseItem.fir_number)}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.court_name || '-'}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.accused_name || '-'}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.ipc_sections || '-'}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.original_suit || '-'}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.client}
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      <span className={`status-badge ${(caseItem.status || 'Open').toLowerCase()}`}>
                        {caseItem.status || 'Open'}
                      </span>
                    </td>
                    <td
                      onClick={() => navigate(`/cases/${caseItem.id}`)}
                      style={{ cursor: 'pointer' }}
                    >
                      {caseItem.nextHearing}
                    </td>
                    <td>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', fontSize: '0.8em' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                          {docCount > 0 ? (
                            <>
                              <span style={{ color: '#28a745' }}>📎</span>
                              <span>{docCount} files</span>
                            </>
                          ) : (
                            <>
                              <span style={{ color: '#6c757d' }}>📄</span>
                              <span>No files</span>
                            </>
                          )}
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                          {historyDocCount > 0 ? (
                            <>
                              <span style={{ color: '#007bff' }}>📚</span>
                              <span>{historyDocCount} history</span>
                            </>
                          ) : (
                            <>
                              <span style={{ color: '#6c757d' }}>📋</span>
                              <span>No history</span>
                            </>
                          )}
                        </div>
                      </div>
                    </td>
                    <td>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            navigate(`/cases/${caseItem.id}`);
                          }}
                          style={{
                            background: '#007bff',
                            color: 'white',
                            border: 'none',
                            padding: '4px 8px',
                            borderRadius: '3px',
                            cursor: 'pointer',
                            fontSize: '0.75rem'
                          }}
                        >
                          📤 Upload Docs
                        </button>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            startEditing(caseItem);
                          }}
                          style={{
                            background: '#28a745',
                            color: 'white',
                            border: 'none',
                            padding: '4px 8px',
                            borderRadius: '3px',
                            cursor: 'pointer',
                            fontSize: '0.75rem'
                          }}
                        >
                          ✏️ Edit
                        </button>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            deleteCase(caseItem.id);
                          }}
                          disabled={loading}
                          style={{
                            background: '#dc3545',
                            color: 'white',
                            border: 'none',
                            padding: '4px 8px',
                            borderRadius: '3px',
                            cursor: loading ? 'not-allowed' : 'pointer',
                            fontSize: '0.75rem'
                          }}
                        >
                          {loading ? 'Deleting...' : 'Delete'}
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })
            ) : (
              <tr>
                <td colSpan="13" className="no-cases">
                  No cases found matching your criteria.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </main>
    </div>
  );
};

export default Cases;
