import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const styles = `
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideIn {
  from { opacity: 0; transform: scale(0.9); }
  to { opacity: 1; transform: scale(1); }
}
`;

const styleSheet = document.createElement("style");
styleSheet.type = "text/css";
styleSheet.innerText = styles;
document.head.appendChild(styleSheet);

const RegisterForm = () => {
  const [role, setRole] = useState("Advocate");
  const [formData, setFormData] = useState({
    username: "",
    password: "",
    name: "",
    email: "",
    phone: "",
    address: ""
  });
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const validateForm = () => {
    const newErrors = {};

    if (!formData.username.trim()) {
      newErrors.username = "Username is required.";
    } else if (formData.username.length < 3) {
      newErrors.username = "Username must be at least 3 characters.";
    } else if (!/^[a-zA-Z0-9_]+$/.test(formData.username)) {
      newErrors.username = "Username can only contain letters, numbers, and underscores.";
    }

    if (!formData.password) {
      newErrors.password = "Password is required.";
    } else if (formData.password.length < 6) {
      newErrors.password = "Password must be at least 6 characters.";
    }

    if (!formData.name.trim()) {
      newErrors.name = "Name is required.";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email is required.";
    } else if (!formData.email.includes('@')) {
      newErrors.email = "Email must contain @ symbol.";
    }

    if (!formData.phone.trim()) {
      newErrors.phone = "Phone number is required.";
    } else if (formData.phone.length !== 10 || !/^\d{10}$/.test(formData.phone)) {
      newErrors.phone = "Phone number must be exactly 10 digits.";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrors({});
    if (!validateForm()) return;

    setIsLoading(true);
    console.log("Registration data:", { role, ...formData });

    try {
      const endpoint = role === "Advocate" ? "/register/advocate" : "/register/client";
      const response = await fetch(`http://localhost:5000${endpoint}`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (data.success) {
        alert("Registration successful! Please login with your credentials.");
        navigate("/");
      } else {
        setErrors({ general: data.message || "Registration failed. Please try again." });
      }
    } catch (error) {
      console.error("Registration error:", error);
      setErrors({ general: "Registration failed. Please try again." });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
      }}
    >
      <h1 style={{ fontWeight: "bold", marginBottom: "20px" }}>Registration Portal</h1>

      <div
        style={{
          border: "1px solid #ddd",
          borderRadius: "15px",
          padding: "30px",
          width: "400px",
          boxShadow: "0 8px 20px rgba(0, 0, 0, 0.15)",
          background: "linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)",
          animation: "slideIn 0.5s ease-out"
        }}
      >
        <h2 style={{ textAlign: "center" }}>Register</h2>

        {errors.general && (
          <div style={{
            color: "red",
            marginBottom: "15px",
            padding: "10px",
            border: "1px solid red",
            borderRadius: "5px",
            backgroundColor: "#ffe6e6",
            animation: "fadeIn 0.5s"
          }}>
            {errors.general}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>
              Role:
            </label>
            <select
              value={role}
              onChange={(e) => setRole(e.target.value)}
              style={{
                width: "100%",
                padding: "8px",
                border: "1px solid #ccc",
                borderRadius: "4px",
                fontSize: "16px"
              }}
            >
              <option value="Advocate">Advocate</option>
              <option value="Client">Client</option>
            </select>
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>
              Username:
            </label>
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                border: errors.username ? "1px solid red" : "1px solid #ccc",
                borderRadius: "4px",
                fontSize: "16px",
                boxSizing: "border-box"
              }}
            />
            {errors.username && (
              <div style={{
                color: "red",
                fontSize: "12px",
                marginTop: "5px",
                animation: "fadeIn 0.3s"
              }}>
                {errors.username}
              </div>
            )}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>
              Password:
            </label>
            <div style={{ position: 'relative' }}>
              <input
                type={showPassword ? "text" : "password"}
                name="password"
                value={formData.password}
                onChange={handleInputChange}
                required
                style={{
                  width: "100%",
                  padding: "8px",
                  paddingRight: "45px",
                  border: errors.password ? "1px solid red" : "1px solid #ccc",
                  borderRadius: "4px",
                  fontSize: "16px",
                  boxSizing: "border-box"
                }}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                style={{
                  position: 'absolute',
                  right: '10px',
                  top: '50%',
                  transform: 'translateY(-50%)',
                  background: 'none',
                  border: 'none',
                  cursor: 'pointer',
                  fontSize: '18px',
                  color: '#28a745'
                }}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? "🙈" : "👁️"}
              </button>
            </div>
            {errors.password && (
              <div style={{
                color: "red",
                fontSize: "12px",
                marginTop: "5px",
                animation: "fadeIn 0.3s"
              }}>
                {errors.password}
              </div>
            )}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>
              Name:
            </label>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                border: errors.name ? "1px solid red" : "1px solid #ccc",
                borderRadius: "4px",
                fontSize: "16px"
              }}
            />
            {errors.name && (
              <div style={{
                color: "red",
                fontSize: "12px",
                marginTop: "5px",
                animation: "fadeIn 0.3s"
              }}>
                {errors.name}
              </div>
            )}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>
              Email:
            </label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                border: errors.email ? "1px solid red" : "1px solid #ccc",
                borderRadius: "4px",
                fontSize: "16px"
              }}
            />
            {errors.email && (
              <div style={{
                color: "red",
                fontSize: "12px",
                marginTop: "5px",
                animation: "fadeIn 0.3s"
              }}>
                {errors.email}
              </div>
            )}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>
              Phone:
            </label>
            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                border: errors.phone ? "1px solid red" : "1px solid #ccc",
                borderRadius: "4px",
                fontSize: "16px"
              }}
            />
            {errors.phone && (
              <div style={{
                color: "red",
                fontSize: "12px",
                marginTop: "5px",
                animation: "fadeIn 0.3s"
              }}>
                {errors.phone}
              </div>
            )}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>
              Address (optional):
            </label>
            <textarea
              name="address"
              value={formData.address}
              onChange={handleInputChange}
              rows="3"
              style={{
                width: "100%",
                padding: "8px",
                border: "1px solid #ccc",
                borderRadius: "4px",
                fontSize: "16px",
                resize: "vertical"
              }}
            />
          </div>

          <button
            type="submit"
            disabled={isLoading}
            style={{
              width: "100%",
              padding: "10px",
              backgroundColor: isLoading ? "#ccc" : "#28a745",
              color: "white",
              border: "none",
              borderRadius: "5px",
              cursor: isLoading ? "not-allowed" : "pointer",
              transition: "background-color 0.3s",
              fontSize: "16px",
              fontWeight: "bold"
            }}
            onMouseOver={(e) => !isLoading && (e.target.style.backgroundColor = "#218838")}
            onMouseOut={(e) => !isLoading && (e.target.style.backgroundColor = "#28a745")}
          >
            {isLoading ? "Registering..." : "Register"}
          </button>
        </form>

        <p style={{ textAlign: "center", marginTop: "15px" }}>
          Already have an account?{" "}
          <a href="/">Login here</a>
        </p>
      </div>
    </div>
  );
};

export default RegisterForm;
