import React, { useState, useEffect, useCallback } from "react";
import { Link } from "react-router-dom";

const Tasks = ({ isStaff = false }) => {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showAssignForm, setShowAssignForm] = useState(false);
  const [assignForm, setAssignForm] = useState({
    title: "",
    description: "",
    assignedTo: "",
    clientId: "",
    caseId: "",
    startDate: "",
    endDate: ""
  });
  const [staffList, setStaffList] = useState([]);
  const [clients, setClients] = useState([]);
  const [cases, setCases] = useState([]);

  const fetchTasks = useCallback(async () => {
    try {
      setLoading(true);
      const username = localStorage.getItem("username");
      let endpoint;
      if (isStaff) {
        endpoint = `/tasks/staff/${username}`;
      } else {
        endpoint = `/tasks/advocate/${username}`;
      }

      const response = await fetch(`http://localhost:5000${endpoint}`);
      if (!response.ok) throw new Error("Failed to fetch tasks");
      const data = await response.json();
      setTasks(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [isStaff]);

  useEffect(() => {
    fetchTasks();
    if (!isStaff) {
      fetchStaff();
      fetchClients();
      fetchCases();
    }
  }, [isStaff, fetchTasks]);

  const fetchStaff = async () => {
    try {
      const username = localStorage.getItem("username");
      const response = await fetch(`http://localhost:5000/staff/${username}`);
      if (!response.ok) throw new Error("Failed to fetch staff");
      const data = await response.json();
      setStaffList(data);
    } catch (err) {
      console.error("Error fetching staff:", err);
    }
  };

  const fetchClients = async () => {
    try {
      const response = await fetch("http://localhost:5000/clients");
      if (!response.ok) throw new Error("Failed to fetch clients");
      const data = await response.json();
      setClients(data);
    } catch (err) {
      console.error("Error fetching clients:", err);
    }
  };

  const fetchCases = async () => {
    try {
      const response = await fetch("http://localhost:5000/cases");
      if (!response.ok) throw new Error("Failed to fetch cases");
      const data = await response.json();
      setCases(data);
    } catch (err) {
      console.error("Error fetching cases:", err);
    }
  };

  const handleAssignTask = async (e) => {
    e.preventDefault();
    try {
      const advocateUsername = localStorage.getItem("username");
      const response = await fetch("http://localhost:5000/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...assignForm, advocateUsername }),
      });

      if (!response.ok) throw new Error("Failed to assign task");
      setShowAssignForm(false);
      setAssignForm({ title: "", description: "", assignedTo: "", clientId: "", caseId: "", startDate: "", endDate: "" });
      fetchTasks();
    } catch (err) {
      setError(err.message);
    }
  };

  const updateTaskStatus = async (taskId, status) => {
    try {
      const staffUsername = localStorage.getItem("username");
      const response = await fetch(`http://localhost:5000/tasks/${taskId}/status`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status, staffUsername }),
      });

      if (!response.ok) throw new Error("Failed to update task status");
      fetchTasks();
    } catch (err) {
      setError(err.message);
    }
  };

  const deleteTask = async (taskId) => {
    if (!window.confirm("Are you sure you want to delete this task?")) return;

    const advocateUsername = localStorage.getItem("username");
    const userRole = localStorage.getItem("role");
    console.log("Delete task - advocateUsername from localStorage:", advocateUsername);
    console.log("Delete task - userRole:", userRole);
    console.log("Delete task - taskId:", taskId);
    console.log("Delete task - all localStorage:", {
      username: localStorage.getItem("username"),
      role: localStorage.getItem("role"),
      clientName: localStorage.getItem("clientName"),
      staffName: localStorage.getItem("staffName")
    });
    if (!advocateUsername || userRole !== "advocate") {
      setError("Only advocates can delete tasks.");
      return;
    }

    try {
      const requestBody = { advocateUsername };
      console.log("Delete task - request body:", requestBody);
      const response = await fetch(`http://localhost:5000/tasks/${taskId}`, {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(requestBody),
      });

      console.log("Delete task - response status:", response.status);
      if (!response.ok) {
        let errorMessage = "Failed to delete task";
        try {
          const errorData = await response.json();
          console.log("Delete task - error data:", errorData);
          errorMessage = errorData.message || errorMessage;
        } catch (e) {
          // If response is not JSON, use status text
          errorMessage = `Failed to delete task: ${response.status} ${response.statusText}`;
        }
        throw new Error(errorMessage);
      }
      fetchTasks();
    } catch (err) {
      console.log("Delete task - error:", err.message);
      setError(err.message);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "Completed": return "#28a745";
      case "In Progress": return "#ffc107";
      default: return "#6c757d";
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        padding: "30px",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      }}
    >
      {/* Header */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
          padding: "20px 30px",
          borderRadius: "15px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
          marginBottom: "30px",
        }}
      >
        <h2 style={{ color: "#333", fontSize: "1.8rem", margin: 0 }}>
          📝 {isStaff ? "My Tasks" : "Task Manager"}
        </h2>

        {!isStaff && (
          <button
            onClick={() => setShowAssignForm(!showAssignForm)}
            style={{
              background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
              color: "white",
              border: "none",
              padding: "10px 20px",
              borderRadius: "8px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
              transition: "0.3s ease",
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-3px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            {showAssignForm ? "Cancel" : "➕ Assign Task"}
          </button>
        )}

        <Link
          to={isStaff ? "/staff-dashboard" : "/dashboard"}
          className="back-button"
          aria-label="Back to Dashboard"
          style={{
            display: "inline-block",
            background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
            color: "white",
            padding: "10px 20px",
            borderRadius: "8px",
            fontWeight: "bold",
            textDecoration: "none",
            boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
            transition: "0.3s ease",
          }}
          onMouseEnter={(e) => (e.target.style.transform = "translateY(-3px)")}
          onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
        >
          ⬅️ Back to Dashboard
        </Link>
      </div>

      {/* Assign Task Form */}
      {showAssignForm && !isStaff && (
        <div
          style={{
            background: "white",
            padding: "30px",
            borderRadius: "15px",
            boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
            marginBottom: "30px",
          }}
        >
          <h3 style={{ marginBottom: "20px", color: "#333" }}>Assign New Task</h3>
          <form onSubmit={handleAssignTask}>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px" }}>
              <div>
                <label style={{ display: "block", marginBottom: "5px", fontWeight: "600" }}>Task Title</label>
                <input
                  type="text"
                  value={assignForm.title}
                  onChange={(e) => setAssignForm({ ...assignForm, title: e.target.value })}
                  required
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "8px",
                    fontSize: "1rem",
                  }}
                />
              </div>
              <div>
                <label style={{ display: "block", marginBottom: "5px", fontWeight: "600" }}>Assign to Staff</label>
                <select
                  value={assignForm.assignedTo}
                  onChange={(e) => setAssignForm({ ...assignForm, assignedTo: e.target.value })}
                  required
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "8px",
                    fontSize: "1rem",
                  }}
                >
                  <option value="">Select Staff</option>
                  {staffList.map((staff) => (
                    <option key={staff.id} value={staff.id}>
                      {staff.name} ({staff.username})
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={{ display: "block", marginBottom: "5px", fontWeight: "600" }}>Client (Optional)</label>
                <select
                  value={assignForm.clientId}
                  onChange={(e) => setAssignForm({ ...assignForm, clientId: e.target.value })}
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "8px",
                    fontSize: "1rem",
                  }}
                >
                  <option value="">Select Client</option>
                  {clients.map((client) => (
                    <option key={client.id} value={client.id}>
                      {client.name}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={{ display: "block", marginBottom: "5px", fontWeight: "600" }}>Case (Optional)</label>
                <select
                  value={assignForm.caseId}
                  onChange={(e) => setAssignForm({ ...assignForm, caseId: e.target.value })}
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "8px",
                    fontSize: "1rem",
                  }}
                >
                  <option value="">Select Case</option>
                  {cases.map((caseItem) => (
                    <option key={caseItem.id} value={caseItem.id}>
                      {caseItem.title}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label style={{ display: "block", marginBottom: "5px", fontWeight: "600" }}>Start Date</label>
                <input
                  type="date"
                  value={assignForm.startDate}
                  onChange={(e) => setAssignForm({ ...assignForm, startDate: e.target.value })}
                  required
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "8px",
                    fontSize: "1rem",
                  }}
                />
              </div>
              <div>
                <label style={{ display: "block", marginBottom: "5px", fontWeight: "600" }}>End Date</label>
                <input
                  type="date"
                  value={assignForm.endDate}
                  onChange={(e) => setAssignForm({ ...assignForm, endDate: e.target.value })}
                  required
                  style={{
                    width: "100%",
                    padding: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "8px",
                    fontSize: "1rem",
                  }}
                />
              </div>
            </div>
            <div style={{ marginTop: "20px" }}>
              <label style={{ display: "block", marginBottom: "5px", fontWeight: "600" }}>Description</label>
              <textarea
                value={assignForm.description}
                onChange={(e) => setAssignForm({ ...assignForm, description: e.target.value })}
                rows="3"
                style={{
                  width: "100%",
                  padding: "10px",
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  fontSize: "1rem",
                }}
              />
            </div>
            <div style={{ marginTop: "20px", textAlign: "right" }}>
              <button
                type="submit"
                style={{
                  padding: "12px 30px",
                  border: "none",
                  borderRadius: "8px",
                  background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                  color: "white",
                  fontWeight: "bold",
                  cursor: "pointer",
                  fontSize: "1rem",
                }}
              >
                Assign Task
              </button>
            </div>
          </form>
        </div>
      )}



      {/* Task List */}
      <div
        style={{
          background: "white",
          borderRadius: "15px",
          padding: "20px",
          boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
        }}
      >
        {loading ? (
          <p style={{ textAlign: "center", color: "#777" }}>Loading tasks...</p>
        ) : error ? (
          <p style={{ textAlign: "center", color: "#e74c3c" }}>Error: {error}</p>
        ) : tasks.length === 0 ? (
          <p style={{ textAlign: "center", color: "#777" }}>No tasks available.</p>
        ) : (
          <ul style={{ listStyle: "none", padding: 0 }}>
            {tasks.map((task) => (
              <li
                key={task.id}
                style={{
                  padding: "15px",
                  borderBottom: "1px solid #eee",
                  background: task.status === "Completed"
                    ? "rgba(40, 167, 69, 0.1)"
                    : task.status === "In Progress"
                    ? "rgba(255, 193, 7, 0.1)"
                    : "transparent",
                  transition: "0.3s ease",
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                  <div style={{ flex: 1 }}>
                    <h4 style={{ margin: "0 0 8px 0", color: "#333" }}>{task.title}</h4>
                    {task.description && (
                      <p style={{ margin: "0 0 8px 0", color: "#666", fontSize: "0.9rem" }}>
                        {task.description}
                      </p>
                    )}
                    <div style={{ display: "flex", gap: "15px", fontSize: "0.85rem", color: "#666" }}>
                      {task.clientName && <span>Client: {task.clientName}</span>}
                      {task.caseTitle && <span>Case: {task.caseTitle}</span>}
                      {task.startDate && <span>Start: {new Date(task.startDate).toLocaleDateString()}</span>}
                      {task.endDate && <span>End: {new Date(task.endDate).toLocaleDateString()}</span>}
                    </div>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: "10px" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                      <span
                        style={{
                          padding: "4px 8px",
                          borderRadius: "4px",
                          fontSize: "0.8rem",
                          fontWeight: "bold",
                          color: "white",
                          backgroundColor: getStatusColor(task.status),
                        }}
                      >
                        {task.status || "Pending"}
                      </span>
                      {!isStaff && (
                        <button
                          onClick={() => deleteTask(task.id)}
                          style={{
                            padding: "4px 8px",
                            border: "none",
                            borderRadius: "4px",
                            background: "#dc3545",
                            color: "white",
                            cursor: "pointer",
                            fontSize: "0.8rem",
                          }}
                          title="Delete Task"
                        >
                          🗑️
                        </button>
                      )}
                    </div>
                    {isStaff && task.status !== "Completed" && (
                      <div style={{ display: "flex", gap: "5px" }}>
                        {task.status !== "In Progress" && (
                          <button
                            onClick={() => updateTaskStatus(task.id, "In Progress")}
                            style={{
                              padding: "4px 8px",
                              border: "none",
                              borderRadius: "4px",
                              background: "#ffc107",
                              color: "white",
                              cursor: "pointer",
                              fontSize: "0.8rem",
                            }}
                          >
                            Start
                          </button>
                        )}
                        <button
                          onClick={() => updateTaskStatus(task.id, "Completed")}
                          style={{
                            padding: "4px 8px",
                            border: "none",
                            borderRadius: "4px",
                            background: "#28a745",
                            color: "white",
                            cursor: "pointer",
                            fontSize: "0.8rem",
                          }}
                        >
                          Complete
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default Tasks;
