import React from "react";
import { Link } from "react-router-dom";

const ClientDashboard = () => {
  const linkStyle = {
    display: "block",
    padding: "15px 20px",
    marginBottom: "10px",
    background: "burlywood",
    color: "white",
    textDecoration: "none",
    borderRadius: "10px",
    fontSize: "16px",
    fontWeight: "bold",
    transition: "background 0.3s ease, transform 0.3s ease",
  };

  const hoverStyle = {
    background: "rgba(255,255,255,0.2)",
    transform: "translateX(5px)",
  };

  return (
    <div style={{
      display: "flex",
      minHeight: "100vh",
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif"
    }}>
      {/* Left Sidebar */}
      <div style={{
        width: "280px",
        background: "burlywood",
        padding: "30px 20px",
        boxShadow: "2px 0 10px rgba(0,0,0,0.1)",
        position: "fixed",
        height: "100vh",
        overflowY: "auto"
      }}>
        <h2 style={{
          color: "white",
          textAlign: "center",
          marginBottom: "30px",
          fontSize: "1.5rem",
          textShadow: "1px 1px 2px rgba(0,0,0,0.3)"
        }}>
          Client Navigation
        </h2>
        <Link to="/client-case-details" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          My Cases
        </Link>
        
        <Link to="/client-billing" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          Billing
        </Link>
        <Link to="/client-communication" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          Communication
        </Link>
      </div>

      {/* Main Content Area */}
      <div style={{
        marginLeft: "280px",
        flex: 1,
        padding: "40px",
        minHeight: "100vh"
      }}>
        <div style={{
          textAlign: "center",
          marginBottom: "50px",
          background: "rgba(255,255,255,0.9)",
          padding: "40px",
          borderRadius: "20px",
          boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
          position: "relative"
        }}>
          <button
            onClick={() => {
              localStorage.clear();
              window.location.href = '/';
            }}
            style={{
              position: "absolute",
              top: "20px",
              right: "20px",
              padding: "10px 20px",
              background: "linear-gradient(135deg, #dc3545 0%, #c82333 100%)",
              color: "white",
              border: "none",
              borderRadius: "8px",
              fontSize: "14px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            🔙 Back to Login
          </button>
          <h1 style={{
            color: "#333",
            fontSize: "3rem",
            marginBottom: "10px",
            textShadow: "2px 2px 4px rgba(0,0,0,0.1)"
          }}>
            ⚖️ Client Dashboard
          </h1>
          <p style={{
            color: "#666",
            fontSize: "1.2rem",
            margin: 0
          }}>
            Welcome to your legal case management portal
          </p>
        </div>
      </div>
    </div>
  );
};

export default ClientDashboard;
