import React, { useState, useEffect } from "react";
import { useNavigate, Link } from "react-router-dom";
import Tasks from "./Tasks";
import AA from "../assets/AA.png";

const StaffDashboard = () => {
  const [activeTab, setActiveTab] = useState("clients");
  const [staffName, setStaffName] = useState("");
  const [advocateName, setAdvocateName] = useState("");
  const [clients, setClients] = useState([]);
  const [cases, setCases] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const role = localStorage.getItem("role");
    if (role !== "staff") {
      navigate("/");
      return;
    }

    setStaffName(localStorage.getItem("staffName") || "");
    setAdvocateName(localStorage.getItem("advocateName") || "");
    fetchStaffData();
  }, [navigate]);

  const fetchStaffData = async () => {
    try {
      const username = localStorage.getItem("username");
      const role = localStorage.getItem("role");
      console.log("Current username from localStorage:", username);
      console.log("Current role from localStorage:", role);

      if (!username || role !== "staff") {
        console.log("No username or not staff role, redirecting...");
        navigate("/");
        return;
      }

      // Fetch clients and cases assigned to this staff
      console.log("Fetching clients from:", `http://localhost:5000/clients/staff/${username}`);
      const [clientsResponse, casesResponse] = await Promise.all([
        fetch(`http://localhost:5000/clients/staff/${username}`),
        fetch(`http://localhost:5000/cases/staff/${username}`)
      ]);

      console.log("Clients response status:", clientsResponse.status);
      console.log("Cases response status:", casesResponse.status);

      let clientsData = [];
      let casesData = [];

      if (clientsResponse.ok) {
        clientsData = await clientsResponse.json();
        console.log("Fetched clients data:", clientsData);
        console.log("Clients array length:", clientsData.length);
        console.log("Individual clients:", clientsData.map(c => c.name));
      } else {
        console.log("Failed to fetch clients, response:", await clientsResponse.text());
      }

      if (casesResponse.ok) {
        casesData = await casesResponse.json();
        console.log("Fetched cases data:", casesData);
        console.log("Cases array length:", casesData.length);
      } else {
        console.log("Failed to fetch cases, response:", await casesResponse.text());
      }

      console.log("About to set clients in state:", clientsData);
      setClients(clientsData);
      setCases(casesData);
      console.log("Set clients and cases in state");
    } catch (error) {
      console.error("Error fetching staff data:", error);
      setClients([]);
      setCases([]);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  const tabs = [
    { id: "clients", label: "My Clients", icon: "👥" },
    { id: "cases", label: "Case Details", icon: "📋" },
    { id: "tasks", label: "My Tasks", icon: "✅" },
    { id: "analytics", label: "Case Analysis", icon: "📊" },
  ];

  return (
    <div style={{ minHeight: "100vh", backgroundImage: `url(${AA})`, backgroundSize: "cover", backgroundPosition: "center", display: "flex" }}>
      {/* Left Sidebar */}
      <aside style={{
        width: "280px",
        background: "burlywood",
        minHeight: "100vh",
        boxShadow: "2px 0 10px rgba(0,0,0,0.1)",
        display: "flex",
        flexDirection: "column"
      }}>
        {/* Header in Sidebar */}
        <div style={{
          padding: "20px",
          borderBottom: "1px solid rgba(255,255,255,0.2)",
          background: "rgba(0,0,0,0.1)"
        }}>
          <h2 style={{ margin: 0, fontSize: "20px", fontWeight: "700", color: "white" }}>
            Staff Portal
          </h2>
          <p style={{ margin: "5px 0 0 0", opacity: 0.9, color: "white", fontSize: "14px" }}>
            {staffName}
          </p>
          <p style={{ margin: "2px 0 0 0", opacity: 0.8, color: "white", fontSize: "12px" }}>
            Under: {advocateName}
          </p>
        </div>

        {/* Navigation Menu */}
        <nav style={{ flex: 1, padding: "20px 0" }}>
          <div style={{ display: "flex", flexDirection: "column" }}>
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                style={{
                  padding: "15px 25px",
                  border: "none",
                  background: activeTab === tab.id ? "#667eea" : "transparent",
                  color: activeTab === tab.id ? "white" : "rgba(255,255,255,0.9)",
                  cursor: "pointer",
                  fontSize: "16px",
                  fontWeight: "600",
                  borderRight: activeTab === tab.id ? "4px solid #fff" : "4px solid transparent",
                  transition: "all 0.3s ease",
                  display: "flex",
                  alignItems: "center",
                  gap: "12px",
                  textAlign: "left",
                  width: "100%"
                }}
                onMouseOver={(e) => {
                  if (activeTab !== tab.id) {
                    e.target.style.background = "rgba(255,255,255,0.1)";
                  }
                }}
                onMouseOut={(e) => {
                  if (activeTab !== tab.id) {
                    e.target.style.background = "transparent";
                  }
                }}
              >
                <span style={{ fontSize: "20px" }}>{tab.icon}</span>
                <span>{tab.label}</span>
              </button>
            ))}
          </div>
        </nav>

        {/* Logout Button */}
        <div style={{
          padding: "20px",
          borderTop: "1px solid rgba(255,255,255,0.2)"
        }}>
          <button
            onClick={handleLogout}
            style={{
              background: "rgba(255,255,255,0.2)",
              color: "white",
              border: "1px solid rgba(255,255,255,0.3)",
              padding: "12px 20px",
              borderRadius: "8px",
              cursor: "pointer",
              fontSize: "14px",
              fontWeight: "600",
              transition: "all 0.3s ease",
              width: "100%"
            }}
            onMouseOver={(e) => e.target.style.background = "rgba(255,255,255,0.3)"}
            onMouseOut={(e) => e.target.style.background = "rgba(255,255,255,0.2)"}
          >
            🔙 Back to Login
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main style={{
        flex: 1,
        padding: "30px",
        minHeight: "100vh",
        overflowY: "auto"
      }}>
        {activeTab === "clients" && (
          <div>
            <h2 style={{ marginBottom: "20px", color: "white" }}>Client Details</h2>
            {loading ? (
              <p>Loading clients...</p>
            ) : clients.length === 0 ? (
              <p>No clients assigned.</p>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: "30px" }}>
                {clients.map((client) => {
                  const clientCases = cases.filter(caseItem => caseItem.client === client.name);
                  return (
                    <div key={client.id} style={{
                      background: "#f8f9fa",
                      padding: "25px",
                      borderRadius: "15px",
                      boxShadow: "0 6px 20px rgba(0,0,0,0.1)",
                      border: "1px solid #e1e5e9"
                    }}>
                      {/* Client Header */}
                      <div style={{
                        borderBottom: "2px solid #667eea",
                        paddingBottom: "15px",
                        marginBottom: "20px"
                      }}>
                        <h3 style={{ margin: "0 0 10px 0", color: "#667eea", fontSize: "24px" }}>{client.name}</h3>
                        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "10px" }}>
                          <p style={{ margin: "5px 0", color: "#666" }}><strong>Email:</strong> {client.email}</p>
                          <p style={{ margin: "5px 0", color: "#666" }}><strong>Phone:</strong> {client.phone || "N/A"}</p>
                          <p style={{ margin: "5px 0", color: "#666" }}><strong>Address:</strong> {client.address || "N/A"}</p>
                        </div>
                      </div>

                      {/* Client Cases */}
                      <div>
                        <h4 style={{ margin: "0 0 15px 0", color: "#333", fontSize: "18px" }}>
                          Associated Cases ({clientCases.length})
                        </h4>
                        {clientCases.length === 0 ? (
                          <p style={{ color: "#666", fontStyle: "italic" }}>No cases assigned to this client.</p>
                        ) : (
                          <div style={{ display: "grid", gap: "15px", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))" }}>
                            {clientCases.map((caseItem) => (
                              <Link
                                key={caseItem.id}
                                to={`/cases/${caseItem.id}`}
                                style={{ textDecoration: "none" }}
                              >
                                <div style={{
                                  background: "white",
                                  padding: "15px",
                                  borderRadius: "8px",
                                  boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
                                  border: "1px solid #e1e5e9",
                                  cursor: "pointer",
                                  transition: "all 0.3s ease"
                                }}
                                onMouseOver={(e) => {
                                  e.currentTarget.style.transform = "translateY(-2px)";
                                  e.currentTarget.style.boxShadow = "0 4px 15px rgba(0,0,0,0.15)";
                                }}
                                onMouseOut={(e) => {
                                  e.currentTarget.style.transform = "translateY(0)";
                                  e.currentTarget.style.boxShadow = "0 2px 8px rgba(0,0,0,0.1)";
                                }}
                                >
                                  <h5 style={{ margin: "0 0 8px 0", color: "#667eea" }}>{caseItem.title}</h5>
                                  <p style={{ margin: "3px 0", color: "#666", fontSize: "14px" }}>
                                    <strong>Status:</strong>
                                    <span style={{
                                      padding: "2px 6px",
                                      borderRadius: "8px",
                                      fontSize: "0.75rem",
                                      fontWeight: "bold",
                                      marginLeft: "5px",
                                      background: caseItem.status === 'Open' ? '#28a745' : caseItem.status === 'Closed' ? '#dc3545' : '#ffc107',
                                      color: "white"
                                    }}>
                                      {caseItem.status}
                                    </span>
                                  </p>
                                  <p style={{ margin: "3px 0", color: "#666", fontSize: "14px" }}>
                                    <strong>Start Date:</strong> {caseItem.created_at ? new Date(caseItem.created_at).toLocaleDateString() : "N/A"}
                                  </p>
                                  <p style={{ margin: "3px 0", color: "#666", fontSize: "14px" }}>
                                    <strong>Next Hearing:</strong> {caseItem.nextHearing || "Not scheduled"}
                                  </p>
                                  <div style={{
                                    marginTop: "10px",
                                    padding: "6px 10px",
                                    background: "#667eea",
                                    color: "white",
                                    borderRadius: "4px",
                                    textAlign: "center",
                                    fontSize: "0.8rem",
                                    fontWeight: "bold"
                                  }}>
                                    View Case Details →
                                  </div>
                                </div>
                              </Link>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {activeTab === "cases" && (
          <div>
            <h2 style={{ marginBottom: "20px", color: "white" }}>Case Details</h2>
            {loading ? (
              <p>Loading cases...</p>
            ) : cases.length === 0 ? (
              <p>No cases found.</p>
            ) : (
              <div style={{ display: "grid", gap: "20px", gridTemplateColumns: "repeat(auto-fit, minmax(400px, 1fr))" }}>
                {cases.map((caseItem) => (
                  <Link
                    key={caseItem.id}
                    to={`/cases/${caseItem.id}`}
                    style={{ textDecoration: "none" }}
                  >
                    <div style={{
                      background: "#f8f9fa",
                      padding: "20px",
                      borderRadius: "10px",
                      boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
                      border: "1px solid #e1e5e9",
                      cursor: "pointer",
                      transition: "all 0.3s ease",
                      height: "100%"
                    }}
                    onMouseOver={(e) => {
                      e.currentTarget.style.transform = "translateY(-5px)";
                      e.currentTarget.style.boxShadow = "0 8px 25px rgba(0,0,0,0.15)";
                    }}
                    onMouseOut={(e) => {
                      e.currentTarget.style.transform = "translateY(0)";
                      e.currentTarget.style.boxShadow = "0 4px 15px rgba(0,0,0,0.1)";
                    }}
                    >
                      <h3 style={{ margin: "0 0 10px 0", color: "#667eea" }}>{caseItem.title}</h3>
                      <p style={{ margin: "5px 0", color: "#666" }}><strong>Client:</strong> {caseItem.client}</p>
                      <p style={{ margin: "5px 0", color: "#666" }}><strong>Status:</strong>
                        <span style={{
                          padding: "2px 8px",
                          borderRadius: "10px",
                          fontSize: "0.8rem",
                          fontWeight: "bold",
                          marginLeft: "5px",
                          background: caseItem.status === 'Open' ? '#28a745' : caseItem.status === 'Closed' ? '#dc3545' : '#ffc107',
                          color: "white"
                        }}>
                          {caseItem.status}
                        </span>
                      </p>
                      <p style={{ margin: "5px 0", color: "#666" }}><strong>Start Date:</strong> {caseItem.created_at ? new Date(caseItem.created_at).toLocaleDateString() : "N/A"}</p>
                      <p style={{ margin: "5px 0", color: "#666" }}><strong>Next Hearing:</strong> {caseItem.nextHearing || "Not scheduled"}</p>
                      <div style={{
                        marginTop: "15px",
                        padding: "8px 12px",
                        background: "#667eea",
                        color: "white",
                        borderRadius: "5px",
                        textAlign: "center",
                        fontSize: "0.9rem",
                        fontWeight: "bold"
                      }}>
                        Click to View Details →
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === "tasks" && <Tasks isStaff={true} />}

        {activeTab === "analytics" && (
          <div>
            <h2 style={{ marginBottom: "20px", color: "white" }}>Case Analysis Dashboard</h2>
            <p style={{ marginBottom: "30px", color: "white", fontSize: "16px" }}>
              Comprehensive analytics and insights for cases handled by staff
            </p>

            {/* Key Metrics Overview */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <div style={{
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                padding: '25px',
                borderRadius: '15px',
                textAlign: 'center',
                color: 'white',
                boxShadow: '0 8px 25px rgba(102, 126, 234, 0.3)'
              }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '18px' }}>Total Cases Handled</h3>
                <p style={{ fontSize: '2.5rem', fontWeight: 'bold', margin: '0' }}>
                  {cases.length}
                </p>
              </div>

              <div style={{
                background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)',
                padding: '25px',
                borderRadius: '15px',
                textAlign: 'center',
                color: 'white',
                boxShadow: '0 8px 25px rgba(245, 87, 108, 0.3)'
              }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '18px' }}>Active Cases</h3>
                <p style={{ fontSize: '2.5rem', fontWeight: 'bold', margin: '0' }}>
                  {cases.filter(c => c.status?.toLowerCase() === 'open').length}
                </p>
              </div>

              <div style={{
                background: 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)',
                padding: '25px',
                borderRadius: '15px',
                textAlign: 'center',
                color: 'white',
                boxShadow: '0 8px 25px rgba(79, 172, 254, 0.3)'
              }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '18px' }}>Resolved Cases</h3>
                <p style={{ fontSize: '2.5rem', fontWeight: 'bold', margin: '0' }}>
                  {cases.filter(c => c.status?.toLowerCase() === 'closed').length}
                </p>
              </div>

              <div style={{
                background: 'linear-gradient(135deg, #43e97b 0%, #38f9d7 100%)',
                padding: '25px',
                borderRadius: '15px',
                textAlign: 'center',
                color: 'white',
                boxShadow: '0 8px 25px rgba(67, 233, 123, 0.3)'
              }}>
                <h3 style={{ margin: '0 0 10px 0', fontSize: '18px' }}>Success Rate</h3>
                <p style={{ fontSize: '2.5rem', fontWeight: 'bold', margin: '0' }}>
                  {cases.length > 0 ? ((cases.filter(c => c.status?.toLowerCase() === 'closed').length / cases.length) * 100).toFixed(1) : 0}%
                </p>
              </div>
            </div>

            {/* Quick Actions */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <Link to="/staff-case-analytics" style={{ textDecoration: 'none' }}>
                <div style={{
                  background: '#f8f9fa',
                  padding: '25px',
                  borderRadius: '15px',
                  textAlign: 'center',
                  cursor: 'pointer',
                  transition: 'all 0.3s ease',
                  border: '2px solid #667eea',
                  boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
                }}
                onMouseOver={(e) => {
                  e.currentTarget.style.transform = 'translateY(-5px)';
                  e.currentTarget.style.boxShadow = '0 8px 25px rgba(102, 126, 234, 0.3)';
                }}
                onMouseOut={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.boxShadow = '0 4px 15px rgba(0,0,0,0.1)';
                }}
                >
                  <h3 style={{ margin: '0 0 10px 0', color: '#667eea', fontSize: '18px' }}>📊 Detailed Analytics</h3>
                  <p style={{ margin: '0', color: '#666' }}>View comprehensive charts and graphs</p>
                </div>
              </Link>

              <div style={{
                background: '#f8f9fa',
                padding: '25px',
                borderRadius: '15px',
                textAlign: 'center',
                cursor: 'pointer',
                transition: 'all 0.3s ease',
                border: '2px solid #28a745',
                boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
              }}
              onClick={() => setActiveTab('cases')}
              onMouseOver={(e) => {
                e.currentTarget.style.transform = 'translateY(-5px)';
                e.currentTarget.style.boxShadow = '0 8px 25px rgba(40, 167, 69, 0.3)';
              }}
              onMouseOut={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = '0 4px 15px rgba(0,0,0,0.1)';
              }}
              >
                <h3 style={{ margin: '0 0 10px 0', color: '#28a745', fontSize: '18px' }}>📋 View All Cases</h3>
                <p style={{ margin: '0', color: '#666' }}>Browse and manage case details</p>
              </div>
            </div>

            {/* Recent Case Activity */}
            <div style={{ background: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }}>
              <h3 style={{ marginBottom: '20px', color: '#333' }}>📈 Recent Case Activity</h3>
              {loading ? (
                <p>Loading recent activity...</p>
              ) : cases.length === 0 ? (
                <p>No recent case activity.</p>
              ) : (
                <div style={{ display: 'grid', gap: '15px' }}>
                  {cases.slice(0, 5).map((caseItem, index) => (
                    <div key={caseItem.id} style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center',
                      padding: '15px',
                      background: index % 2 === 0 ? '#f8f9fa' : 'white',
                      borderRadius: '8px',
                      border: '1px solid #e9ecef'
                    }}>
                      <div>
                        <h4 style={{ margin: '0 0 5px 0', color: '#667eea' }}>{caseItem.title}</h4>
                        <p style={{ margin: '0', color: '#666', fontSize: '14px' }}>
                          Client: {caseItem.client} • Created: {caseItem.created_at ? new Date(caseItem.created_at).toLocaleDateString() : 'N/A'}
                        </p>
                      </div>
                      <div style={{ textAlign: 'right' }}>
                        <span style={{
                          padding: '4px 12px',
                          borderRadius: '20px',
                          fontSize: '12px',
                          fontWeight: 'bold',
                          background: caseItem.status === 'Open' ? '#28a745' : caseItem.status === 'Closed' ? '#dc3545' : '#ffc107',
                          color: 'white'
                        }}>
                          {caseItem.status}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default StaffDashboard;
