import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";

const Dashboard = () => {
  const [clients, setClients] = useState([]);
  const [staff, setStaff] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [showAddClient, setShowAddClient] = useState(false);
  const [showAddCase, setShowAddCase] = useState(false);
  const [showAddStaff, setShowAddStaff] = useState(false);
  // const [showAddBilling, setShowAddBilling] = useState(false);
  const [clientForm, setClientForm] = useState({ name: '', email: '', phone: '', address: '', username: '', password: '' });
  const [caseForm, setCaseForm] = useState({
    case_id: '',
    title: '',
    case_type: '',
    fir_number: '',
    court_name: '',
    accused_name: '',
    ipc_sections: '',
    original_suit: '',
    status: 'Open',
    nextHearing: '',
    client: ''
  });
  const [staffForm, setStaffForm] = useState({ name: '', email: '', phone: '', address: '', username: '', password: '' });
  const [billingForm, setBillingForm] = useState({
    client: '',
    case_id: '',
    case_description: '',
    staff_handling: '',
    description: '',
    amount: '',
    amount_to_pay: '',
    status: 'Pending',
    dueDate: ''
  });
  const [message, setMessage] = useState('');
  const [currentTime, setCurrentTime] = useState(new Date());

  const linkStyle = {
    display: "block",
    padding: "15px 20px",
    marginBottom: "10px",
    background: "burlywood",
    color: "white",
    textDecoration: "none",
    borderRadius: "10px",
    fontSize: "16px",
    fontWeight: "bold",
    transition: "background 0.3s ease, transform 0.3s ease",
  };

  const hoverStyle = {
    background: "rgba(255,255,255,0.2)",
    transform: "translateX(5px)",
  };

  useEffect(() => {
    fetchClients();
    fetchStaffAndTasks();
  }, []);

  const fetchStaffAndTasks = async () => {
    try {
      const advocateUsername = localStorage.getItem('username');
      if (!advocateUsername) {
        console.error('No advocate username found in localStorage');
        return;
      }
      const [staffResponse, tasksResponse] = await Promise.all([
        fetch(`http://localhost:5000/staff/${advocateUsername}`),
        fetch(`http://localhost:5000/tasks/advocate/${advocateUsername}`)
      ]);

      if (staffResponse.ok) {
        const staffData = await staffResponse.json();
        setStaff(staffData);
      }

      if (tasksResponse.ok) {
        const tasksData = await tasksResponse.json();
        setTasks(tasksData);
      }
    } catch (error) {
      console.error('Error fetching staff and tasks:', error);
    }
  };

  const fetchClients = async () => {
    try {
      const response = await fetch('http://localhost:5000/clients');
      const data = await response.json();
      setClients(data);
    } catch (error) {
      console.error('Error fetching clients:', error);
    }
  };

  const handleAddClient = async (e) => {
    e.preventDefault();
    const advocateUsername = localStorage.getItem('username');
    if (!advocateUsername) {
      setMessage('You must be logged in as an advocate to add clients.');
      return;
    }
    try {
      const response = await fetch('http://localhost:5000/clients', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...clientForm, advocateUsername }),
      });
      const data = await response.json();
      if (data.success) {
        setMessage('Client added successfully!');
        setClientForm({ name: '', email: '', phone: '', address: '', username: '', password: '' });
        setShowAddClient(false);
        fetchClients();
      } else {
        setMessage(data.message);
      }
    } catch (error) {
      setMessage('Error adding client.');
    }
  };

  const handleAddCase = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5000/cases', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(caseForm),
      });
      const data = await response.json();
      if (data.success) {
        setMessage('Case added successfully!');
        setCaseForm({
          case_id: '',
          title: '',
          case_type: '',
          fir_number: '',
          court_name: '',
          accused_name: '',
          ipc_sections: '',
          status: 'Open',
          nextHearing: '',
          client: ''
        });
        setShowAddCase(false);
        // Navigate to cases page to show the new case
        window.location.href = '/cases';
      } else {
        setMessage(data.message);
      }
    } catch (error) {
      setMessage('Error adding case.');
    }
  };

  const handleAddStaff = async (e) => {
    e.preventDefault();
    const advocateUsername = localStorage.getItem('username');
    if (!advocateUsername) {
      setMessage('You must be logged in as an advocate to add staff.');
      return;
    }
    try {
      const response = await fetch('http://localhost:5000/staff', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...staffForm, advocateUsername }),
      });
      const data = await response.json();
      if (data.success) {
        setMessage('Staff added successfully!');
        setStaffForm({ name: '', email: '', phone: '', address: '', username: '', password: '' });
        setShowAddStaff(false);
        fetchStaffAndTasks(); // Refresh staff list
      } else {
        setMessage(data.message);
      }
    } catch (error) {
      setMessage('Error adding staff.');
    }
  };



  return (
    <div style={{
      display: "flex",
      minHeight: "100vh",
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif"
    }}>
      {/* Left Sidebar */}
      <div style={{
        width: "280px",
        background: "burlywood",
        padding: "30px 20px",
        boxShadow: "2px 0 10px rgba(0,0,0,0.1)",
        position: "fixed",
        height: "100vh",
        overflowY: "auto"
      }}>
        <h2 style={{
          color: "white",
          textAlign: "center",
          marginBottom: "30px",
          fontSize: "1.5rem",
          textShadow: "1px 1px 2px rgba(0,0,0,0.3)"
        }}>
           Navigation
        </h2>
        <Link to="/introduction" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
           Introduction
        </Link>
        
      
        
        <Link to="/tasks" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          Tasks
        </Link>
        <Link to="/cases" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          Cases
        </Link>
        <Link to="/clients" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          Clients
        </Link>
        <Link to="/billing" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          Billing
        </Link>

        
        <Link to="/staff" style={linkStyle} onMouseEnter={(e) => Object.assign(e.target.style, hoverStyle)} onMouseLeave={(e) => Object.assign(e.target.style, linkStyle)}>
          Staff
        </Link>

        
      </div>

      {/* Main Content Area */}
      <div style={{
        marginLeft: "280px",
        flex: 1,
        padding: "40px",
        minHeight: "100vh"
      }}>
        <div style={{
          textAlign: "center",
          marginBottom: "50px",
          background: "rgba(255,255,255,0.9)",
          padding: "40px",
          borderRadius: "20px",
          boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
          position: "relative"
        }}>
          <button
            onClick={() => {
              localStorage.clear();
              window.location.href = '/';
            }}
            style={{
              position: "absolute",
              top: "20px",
              right: "20px",
              padding: "10px 20px",
              background: "linear-gradient(135deg, #dc3545 0%, #c82333 100%)",
              color: "white",
              border: "none",
              borderRadius: "8px",
              fontSize: "14px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            🔙 Back to Login
          </button>
          <h1 style={{
            color: "#333",
            fontSize: "3rem",
            marginBottom: "10px",
            textShadow: "2px 2px 4px rgba(0,0,0,0.1)"
          }}>
            ⚖️ Advocate Dashboard
          </h1>
          <p style={{
            color: "#666",
            fontSize: "1.2rem",
            margin: 0
          }}>
            Manage your legal practice efficiently and professionally
          </p>
          <p style={{
            color: "#888",
            fontSize: "1rem",
            margin: "10px 0 0 0",
            fontWeight: "bold"
          }}>
            🕒 Current Time: {currentTime.toLocaleTimeString()}
          </p>
        </div>

        {/* Quick Actions */}
        <div style={{
          display: "flex",
          gap: "20px",
          marginBottom: "30px",
          justifyContent: "center"
        }}>
          <button
            onClick={() => setShowAddClient(!showAddClient)}
            style={{
              padding: "15px 30px",
              background: "linear-gradient(135deg, #28a745 0%, #20c997 100%)",
              color: "white",
              border: "none",
              borderRadius: "10px",
              fontSize: "16px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            ➕ Add Client
          </button>
          <button
            onClick={() => setShowAddCase(!showAddCase)}
            style={{
              padding: "15px 30px",
              background: "linear-gradient(135deg, #007bff 0%, #6610f2 100%)",
              color: "white",
              border: "none",
              borderRadius: "10px",
              fontSize: "16px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            📋 Add Case
          </button>
          <button
            onClick={() => setShowAddStaff(!showAddStaff)}
            style={{
              padding: "15px 30px",
              background: "linear-gradient(135deg, #ff6b6b 0%, #ee5a24 100%)",
              color: "white",
              border: "none",
              borderRadius: "10px",
              fontSize: "16px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            👥 Add Staff
          </button>
          
        </div>

        {message && (
          <div style={{
            textAlign: "center",
            marginBottom: "20px",
            padding: "10px",
            background: message.includes('successfully') ? "#d4edda" : "#f8d7da",
            color: message.includes('successfully') ? "#155724" : "#721c24",
            borderRadius: "5px",
            border: `1px solid ${message.includes('successfully') ? "#c3e6cb" : "#f5c6cb"}`
          }}>
            {message}
          </div>
        )}

        {/* Add Client Form */}
        {showAddClient && (
          <div style={{
            background: "white",
            padding: "30px",
            borderRadius: "15px",
            boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
            marginBottom: "30px",
            maxWidth: "600px",
            margin: "0 auto 30px"
          }}>
            <h3 style={{ textAlign: "center", marginBottom: "20px" }}>Add New Client</h3>
            <form onSubmit={handleAddClient}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "15px" }}>
                <input type="text" placeholder="Name" value={clientForm.name} onChange={(e) => setClientForm({...clientForm, name: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="email" placeholder="Email" value={clientForm.email} onChange={(e) => setClientForm({...clientForm, email: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="tel" placeholder="Phone" value={clientForm.phone} onChange={(e) => setClientForm({...clientForm, phone: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="text" placeholder="Username" value={clientForm.username} onChange={(e) => setClientForm({...clientForm, username: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="password" placeholder="Password" value={clientForm.password} onChange={(e) => setClientForm({...clientForm, password: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <textarea placeholder="Address" value={clientForm.address} onChange={(e) => setClientForm({...clientForm, address: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px", gridColumn: "span 2" }} />
              </div>
              <div style={{ textAlign: "center", marginTop: "20px" }}>
                <button type="submit" style={{ padding: "10px 20px", background: "#28a745", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>Add Client</button>
                <button type="button" onClick={() => setShowAddClient(false)} style={{ padding: "10px 20px", background: "#6c757d", color: "white", border: "none", borderRadius: "5px", cursor: "pointer", marginLeft: "10px" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}

        {/* Add Case Form */}
        {showAddCase && (
          <div style={{
            background: "white",
            padding: "30px",
            borderRadius: "15px",
            boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
            marginBottom: "30px",
            maxWidth: "600px",
            margin: "0 auto 30px"
          }}>
            <h3 style={{ textAlign: "center", marginBottom: "20px" }}>Add New Case</h3>
            <form onSubmit={handleAddCase}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "15px" }}>
                <input type="text" placeholder="Case ID" value={caseForm.case_id} onChange={(e) => setCaseForm({...caseForm, case_id: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="text" placeholder="Case Title *" value={caseForm.title} onChange={(e) => setCaseForm({...caseForm, title: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <select value={caseForm.case_type} onChange={(e) => setCaseForm({...caseForm, case_type: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }}>
                  <option value="">Select Case Type</option>
                  <option value="Criminal">Criminal</option>
                  <option value="Civil">Civil</option>
                  <option value="Family">Family</option>
                  <option value="Corporate">Corporate</option>
                  <option value="Property">Property</option>
                  <option value="Other">Other</option>
                </select>
                <input type="text" placeholder="FIR Number" value={caseForm.fir_number} onChange={(e) => setCaseForm({...caseForm, fir_number: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="text" placeholder="Court Name" value={caseForm.court_name} onChange={(e) => setCaseForm({...caseForm, court_name: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="text" placeholder="Accused Name" value={caseForm.accused_name} onChange={(e) => setCaseForm({...caseForm, accused_name: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="text" placeholder="IPC Sections (comma-separated)" value={caseForm.ipc_sections} onChange={(e) => setCaseForm({...caseForm, ipc_sections: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="text" placeholder="Original Suit" value={caseForm.original_suit} onChange={(e) => setCaseForm({...caseForm, original_suit: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <select value={caseForm.status} onChange={(e) => setCaseForm({...caseForm, status: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }}>
                  <option value="">Select Status *</option>
                  <option value="Open">Open</option>
                  <option value="Closed">Closed</option>
                  <option value="Pending">Pending</option>
                  <option value="In Progress">In Progress</option>
                </select>
                <input type="date" placeholder="Next Hearing Date" value={caseForm.nextHearing} onChange={(e) => setCaseForm({...caseForm, nextHearing: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <select value={caseForm.client} onChange={(e) => setCaseForm({...caseForm, client: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px", gridColumn: "span 2" }}>
                  <option value="">Select Client *</option>
                  {clients.map(client => <option key={client.id} value={client.name}>{client.name}</option>)}
                </select>
              </div>
              <div style={{ textAlign: "center", marginTop: "20px" }}>
                <button type="submit" style={{ padding: "10px 20px", background: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>Add Case</button>
                <button type="button" onClick={() => setShowAddCase(false)} style={{ padding: "10px 20px", background: "#6c757d", color: "white", border: "none", borderRadius: "5px", cursor: "pointer", marginLeft: "10px" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}

        {/* Add Staff Form */}
        {showAddStaff && (
          <div style={{
            background: "white",
            padding: "30px",
            borderRadius: "15px",
            boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
            marginBottom: "30px",
            maxWidth: "600px",
            margin: "0 auto 30px"
          }}>
            <h3 style={{ textAlign: "center", marginBottom: "20px" }}>Add New Staff</h3>
            <form onSubmit={handleAddStaff}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "15px" }}>
                <input type="text" placeholder="Name" value={staffForm.name} onChange={(e) => setStaffForm({...staffForm, name: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="email" placeholder="Email" value={staffForm.email} onChange={(e) => setStaffForm({...staffForm, email: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="tel" placeholder="Phone" value={staffForm.phone} onChange={(e) => setStaffForm({...staffForm, phone: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="text" placeholder="Username" value={staffForm.username} onChange={(e) => setStaffForm({...staffForm, username: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <input type="password" placeholder="Password" value={staffForm.password} onChange={(e) => setStaffForm({...staffForm, password: e.target.value})} required style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px" }} />
                <textarea placeholder="Address" value={staffForm.address} onChange={(e) => setStaffForm({...staffForm, address: e.target.value})} style={{ padding: "10px", border: "1px solid #ccc", borderRadius: "5px", gridColumn: "span 2" }} />
              </div>
              <div style={{ textAlign: "center", marginTop: "20px" }}>
                <button type="submit" style={{ padding: "10px 20px", background: "#ff6b6b", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>Add Staff</button>
                <button type="button" onClick={() => setShowAddStaff(false)} style={{ padding: "10px 20px", background: "#6c757d", color: "white", border: "none", borderRadius: "5px", cursor: "pointer", marginLeft: "10px" }}>Cancel</button>
              </div>
            </form>
          </div>
        )}

        

        {/* Staff Management Section */}
        <div style={{
          background: "white",
          padding: "30px",
          borderRadius: "15px",
          boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
          marginBottom: "30px"
        }}>
          <h3 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>Staff Management</h3>
          {staff.length === 0 ? (
            <p style={{ textAlign: "center", color: "#666" }}>No staff added yet. Use the "Add Staff" button to add your first staff member.</p>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: "20px" }}>
              {staff.map(member => {
                const memberTasks = tasks.filter(task => task.assigned_to === member.id);
                const totalTasks = memberTasks.length;
                const activeTasks = memberTasks.filter(task => task.status === 'In Progress').length;
                const completedTasks = memberTasks.filter(task => task.status === 'Completed').length;
                const pendingTasks = totalTasks - completedTasks;

                return (
                  <div key={member.id} style={{
                    background: "linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%)",
                    padding: "20px",
                    borderRadius: "10px",
                    boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
                    border: "1px solid #dee2e6"
                  }}>
                    <h4 style={{ margin: "0 0 10px 0", color: "#495057" }}>{member.name}</h4>
                    <p style={{ margin: "5px 0", color: "#6c757d" }}>📧 {member.email}</p>
                    <div style={{ marginTop: "15px" }}>
                      <p style={{ margin: "5px 0", fontWeight: "bold", color: "#007bff" }}>📊 Total Tasks: {totalTasks}</p>
                      <p style={{ margin: "5px 0", color: "#ffc107" }}>⏳ Active Tasks: {activeTasks}</p>
                      <p style={{ margin: "5px 0", color: "#17a2b8" }}>⏸️ Pending Tasks: {pendingTasks}</p>
                      <p style={{ margin: "5px 0", color: "#28a745" }}>✅ Completed Tasks: {completedTasks}</p>
                      <p style={{ margin: "5px 0", fontSize: "0.9rem", color: "#495057" }}>Completed: {completedTasks}, Pending: {pendingTasks}</p>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
