// src/App.js
import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Home from "./components/Home";
import LoginForm from "./components/LoginForm";
import RegisterForm from "./components/RegisterForm";
import Dashboard from "./components/Dashboard";
import ClientDashboard from "./components/ClientDashboard";
import CalendarPage from './pages/CalendarPage.jsx';
import Cases from "./components/Cases";
import Tasks from "./components/Tasks";
import Introduction from "./components/Introduction";
import Clients from "./components/Clients";
import Billing from "./components/Billing";
import Accounts from "./components/Accounts";
import Communication from "./components/Communication";
import ClientCases from "./components/ClientCases";
import ClientCaseDetails from "./components/ClientCaseDetails";
import ClientBilling from "./components/ClientBilling";
import ClientCommunication from "./components/ClientCommunication";
import CaseDetail from "./components/CaseDetail";
import AddCase from "./components/AddCase";
import CaseAnalytics from "./components/CaseAnalytics";
import StaffCaseAnalytics from "./components/StaffCaseAnalytics";
import StaffDashboard from "./components/StaffDashboard";
import Staff from "./components/Staff";
import SimilarCasesDocumentManager from "./components/SimilarCasesDocumentManager";
import Reports from "./components/Reports";
import AIChatbot from "./components/AIChatbot";

function App() {
  return (
    <Router>
      <Routes>
        {/* Home page */}
        <Route path="/" element={<Home />} />

        {/* Login page */}
        <Route
          path="/login"
          element={
            <div style={{ textAlign: "center", padding: "20px" }}>
              <LoginForm />
            </div>
          }
        />

        {/* Register page */}
        <Route
          path="/register"
          element={
            <div style={{ textAlign: "center", padding: "20px" }}>
              <RegisterForm />
            </div>
          }
        />

        {/* Advocate dashboard page */}
        <Route path="/advocate-dashboard" element={<Dashboard />} />

        {/* Client dashboard page */}
        <Route path="/client-dashboard" element={<ClientDashboard />} />

        {/* Staff dashboard page */}
        <Route path="/staff-dashboard" element={<StaffDashboard />} />

        {/* General dashboard page */}
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/introduction" element={<Introduction />} />
        <Route path="/calendar" element={<CalendarPage />} />
        <Route path="/cases" element={<Cases />} />
        <Route path="/cases/add" element={<AddCase />} />
        <Route path="/cases/analytics" element={<CaseAnalytics />} />
        <Route path="/tasks" element={<Tasks />} />
        <Route path="/clients" element={<Clients />} />
        <Route path="/billing" element={<Billing />} />
        <Route path="/accounts" element={<Accounts />} />
        <Route path="/communication" element={<Communication />} />
        <Route path="/client-cases" element={<ClientCases />} />
        <Route path="/client-case-details" element={<ClientCaseDetails />} />
        <Route path="/client-billing" element={<ClientBilling />} />
        <Route path="/client-communication" element={<ClientCommunication />} />
        <Route path="/cases/:id" element={<CaseDetail />} />
        <Route path="/staff-case-analytics" element={<StaffCaseAnalytics />} />
        <Route path="/staff" element={<Staff />} />
        <Route path="/similar-cases" element={<SimilarCasesDocumentManager />} />
        <Route path="/client-reports" element={<Reports />} />
      </Routes>
      <AIChatbot />
    </Router>
  );
}

export default App;
