import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";

const Staff = () => {
  const [staff, setStaff] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchStaffAndTasks();
  }, []);

  const fetchStaffAndTasks = async () => {
    try {
      setLoading(true);
      const advocateUsername = localStorage.getItem('username');
      if (!advocateUsername) {
        setError('You must be logged in as an advocate to view staff.');
        setLoading(false);
        return;
      }
      const [staffResponse, tasksResponse] = await Promise.all([
        fetch(`http://localhost:5000/staff/${advocateUsername}`),
        fetch(`http://localhost:5000/tasks/advocate/${advocateUsername}`)
      ]);

      if (staffResponse.ok) {
        const staffData = await staffResponse.json();
        setStaff(staffData);
      } else {
        setError('Failed to fetch staff');
      }

      if (tasksResponse.ok) {
        const tasksData = await tasksResponse.json();
        setTasks(tasksData);
      } else {
        setError('Failed to fetch tasks');
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const deleteStaff = async (staffId) => {
    if (!window.confirm('Are you sure you want to delete this staff member? This action cannot be undone.')) {
      return;
    }

    const advocateUsername = localStorage.getItem('username');
    if (!advocateUsername) {
      alert('You must be logged in as an advocate to delete staff.');
      return;
    }

    try {
      const response = await fetch(`http://localhost:5000/staff/${staffId}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ advocateUsername }),
      });

      const result = await response.json();

      if (response.ok && result.success) {
        alert('Staff member deleted successfully!');
        fetchStaffAndTasks(); // Refresh the data
      } else {
        alert(`Failed to delete staff member: ${result.message}`);
      }
    } catch (error) {
      console.error('Error deleting staff:', error);
      alert('An error occurred while deleting the staff member.');
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        padding: "30px",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      }}
    >
      {/* Header */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
          padding: "20px 30px",
          borderRadius: "15px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
          marginBottom: "30px",
        }}
      >
        <h2 style={{ color: "#333", fontSize: "1.8rem", margin: 0 }}>
          👥 Staff Management
        </h2>

        <Link
          to="/dashboard"
          className="back-button"
          aria-label="Back to Dashboard"
          style={{
            display: "inline-block",
            background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
            color: "white",
            padding: "10px 20px",
            borderRadius: "8px",
            fontWeight: "bold",
            textDecoration: "none",
            boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
            transition: "0.3s ease",
          }}
          onMouseEnter={(e) => (e.target.style.transform = "translateY(-3px)")}
          onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
        >
          ⬅️ Back to Dashboard
        </Link>
      </div>

      {/* Staff List */}
      <div
        style={{
          background: "white",
          borderRadius: "15px",
          padding: "20px",
          boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
        }}
      >
        {loading ? (
          <p style={{ textAlign: "center", color: "#777" }}>Loading staff...</p>
        ) : error ? (
          <p style={{ textAlign: "center", color: "#e74c3c" }}>Error: {error}</p>
        ) : staff.length === 0 ? (
          <p style={{ textAlign: "center", color: "#777" }}>No staff members found.</p>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(350px, 1fr))", gap: "20px" }}>
            {staff.map(member => {
              const memberTasks = tasks.filter(task => task.assigned_to === member.id);
              const totalTasks = memberTasks.length;
              const activeTasks = memberTasks.filter(task => task.status === 'In Progress').length;
              const completedTasks = memberTasks.filter(task => task.status === 'Completed').length;
              const pendingTasks = totalTasks - completedTasks;

              return (
                <div key={member.id} style={{
                  background: "linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%)",
                  padding: "25px",
                  borderRadius: "15px",
                  boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
                  border: "1px solid #dee2e6",
                  transition: "transform 0.3s ease",
                }}
                onMouseEnter={(e) => (e.target.style.transform = "translateY(-5px)")}
                onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
                >
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "15px" }}>
                    <div style={{ display: "flex", alignItems: "center" }}>
                      <div style={{
                        width: "50px",
                        height: "50px",
                        borderRadius: "50%",
                        background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        color: "white",
                        fontSize: "1.2rem",
                        fontWeight: "bold",
                        marginRight: "15px"
                      }}>
                        {member.name.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <h4 style={{ margin: "0 0 5px 0", color: "#495057", fontSize: "1.2rem" }}>{member.name}</h4>
                        <p style={{ margin: "0", color: "#6c757d", fontSize: "0.9rem" }}>@{member.username}</p>
                      </div>
                    </div>
                    <button
                      onClick={() => deleteStaff(member.id)}
                      style={{
                        background: "linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)",
                        color: "white",
                        border: "none",
                        padding: "8px 12px",
                        borderRadius: "6px",
                        fontSize: "0.8rem",
                        fontWeight: "bold",
                        cursor: "pointer",
                        boxShadow: "0 2px 5px rgba(0,0,0,0.2)",
                        transition: "0.3s ease",
                      }}
                      onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
                      onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
                    >
                      🗑️ Delete
                    </button>
                  </div>

                  <div style={{ marginBottom: "15px" }}>
                    <p style={{ margin: "5px 0", color: "#6c757d", fontSize: "0.9rem" }}>📧 {member.email}</p>
                    {member.phone && <p style={{ margin: "5px 0", color: "#6c757d", fontSize: "0.9rem" }}>📞 {member.phone}</p>}
                    {member.address && <p style={{ margin: "5px 0", color: "#6c757d", fontSize: "0.9rem" }}>📍 {member.address}</p>}
                  </div>

                  <div style={{ borderTop: "1px solid #dee2e6", paddingTop: "15px" }}>
                    <h5 style={{ margin: "0 0 10px 0", color: "#495057", fontSize: "1rem" }}>📊 Task Overview</h5>
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
                      <div style={{ textAlign: "center", padding: "10px", background: "#e9ecef", borderRadius: "8px" }}>
                        <p style={{ margin: "0", fontSize: "1.5rem", fontWeight: "bold", color: "#007bff" }}>{totalTasks}</p>
                        <p style={{ margin: "0", fontSize: "0.8rem", color: "#6c757d" }}>Total Tasks</p>
                      </div>
                      <div style={{ textAlign: "center", padding: "10px", background: "#fff3cd", borderRadius: "8px" }}>
                        <p style={{ margin: "0", fontSize: "1.5rem", fontWeight: "bold", color: "#ffc107" }}>{activeTasks}</p>
                        <p style={{ margin: "0", fontSize: "0.8rem", color: "#6c757d" }}>Active</p>
                      </div>
                      <div style={{ textAlign: "center", padding: "10px", background: "#d1ecf1", borderRadius: "8px" }}>
                        <p style={{ margin: "0", fontSize: "1.5rem", fontWeight: "bold", color: "#17a2b8" }}>{pendingTasks}</p>
                        <p style={{ margin: "0", fontSize: "0.8rem", color: "#6c757d" }}>Pending</p>
                      </div>
                      <div style={{ textAlign: "center", padding: "10px", background: "#d4edda", borderRadius: "8px" }}>
                        <p style={{ margin: "0", fontSize: "1.5rem", fontWeight: "bold", color: "#28a745" }}>{completedTasks}</p>
                        <p style={{ margin: "0", fontSize: "0.8rem", color: "#6c757d" }}>Completed</p>
                      </div>
                    </div>
                    <p style={{ margin: "10px 0", fontSize: "0.9rem", color: "#495057" }}>Completed: {completedTasks}, Pending: {pendingTasks}</p>
                  </div>

                  {memberTasks.length > 0 && (
                    <div style={{ marginTop: "15px", borderTop: "1px solid #dee2e6", paddingTop: "15px" }}>
                      <h6 style={{ margin: "0 0 10px 0", color: "#495057", fontSize: "0.9rem" }}>Recent Tasks:</h6>
                      <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
                        {memberTasks.slice(0, 3).map(task => (
                          <li key={task.id} style={{
                            marginBottom: "5px",
                            padding: "5px 10px",
                            background: "white",
                            borderRadius: "5px",
                            fontSize: "0.8rem",
                            color: "#495057"
                          }}>
                            <span style={{
                              padding: "2px 6px",
                              borderRadius: "3px",
                              fontSize: "0.7rem",
                              fontWeight: "bold",
                              color: "white",
                              backgroundColor: task.status === 'Completed' ? '#28a745' : task.status === 'In Progress' ? '#ffc107' : '#6c757d'
                            }}>
                              {task.status}
                            </span>
                            {' '}
                            {task.title.length > 30 ? task.title.substring(0, 30) + '...' : task.title}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default Staff;
