import React, { useEffect, useRef, useState } from "react";
import "./AIChatbot.css";

const initialMessage = {
  role: "assistant",
  content: "Hello! I’m the Legal Case Book Assistant. I can provide general legal information and help with the application. Please do not share confidential case details."
};

export default function AIChatbot() {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState([initialMessage]);
  const [draft, setDraft] = useState("");
  const [isSending, setIsSending] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isSending]);

  const sendMessage = async (event) => {
    event.preventDefault();
    const content = draft.trim();
    if (!content || isSending) return;

    const updatedMessages = [...messages, { role: "user", content }];
    setMessages(updatedMessages);
    setDraft("");
    setIsSending(true);

    try {
      const response = await fetch("http://localhost:5000/api/ai-chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: updatedMessages })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || "Unable to contact the assistant.");
      setMessages((current) => [...current, { role: "assistant", content: data.reply }]);
    } catch (error) {
      setMessages((current) => [...current, { role: "assistant", content: `Sorry, ${error.message}` }]);
    } finally {
      setIsSending(false);
    }
  };

  return (
    <section className="ai-chatbot" aria-label="AI legal information assistant">
      {isOpen && (
        <div className="ai-chatbot__panel">
          <header className="ai-chatbot__header">
            <div><strong>Legal Case Book AI</strong><span>General information only</span></div>
            <button type="button" onClick={() => setIsOpen(false)} aria-label="Close chatbot">×</button>
          </header>
          <div className="ai-chatbot__messages">
            {messages.map((message, index) => (
              <p key={`${message.role}-${index}`} className={`ai-chatbot__message ai-chatbot__message--${message.role}`}>
                {message.content}
              </p>
            ))}
            {isSending && <p className="ai-chatbot__message ai-chatbot__message--assistant">Thinking…</p>}
            <div ref={messagesEndRef} />
          </div>
          <form className="ai-chatbot__form" onSubmit={sendMessage}>
            <label className="sr-only" htmlFor="ai-chat-message">Ask a question</label>
            <textarea id="ai-chat-message" value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Ask a general legal question…" rows="2" maxLength="4000" disabled={isSending} />
            <button type="submit" disabled={isSending || !draft.trim()}>Send</button>
          </form>
        </div>
      )}
      <button className="ai-chatbot__launcher" type="button" onClick={() => setIsOpen((open) => !open)} aria-expanded={isOpen}>
        {isOpen ? "Close AI" : "Ask AI"}
      </button>
    </section>
  );
}
