import React, { useState, useEffect } from "react";
import "./Cases.css";

const SimilarCasesDocumentManager = () => {
  const [cases, setCases] = useState([]);
  const [selectedCases, setSelectedCases] = useState([]);
  const [documentCounts, setDocumentCounts] = useState({});
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [bulkUploading, setBulkUploading] = useState(false);

  useEffect(() => {
    fetchCases();
  }, []);

  const fetchCases = async () => {
    try {
      const response = await fetch("http://localhost:5000/cases");
      if (!response.ok) throw new Error("Failed to fetch cases");
      const data = await response.json();

      // Group cases by title to find similar ones
      const groupedCases = data.reduce((acc, caseItem) => {
        if (!acc[caseItem.title]) acc[caseItem.title] = [];
        acc[caseItem.title].push(caseItem);
        return acc;
      }, {});

      // Find cases with same title but different clients
      const similarCases = Object.values(groupedCases)
        .filter(group => group.length > 1)
        .flat();

      setCases(similarCases);

      // Get document counts for these cases
      const caseIds = similarCases.map(c => c.id).join(',');
      if (caseIds) {
        const countsResponse = await fetch(`http://localhost:5000/cases/document-counts?ids=${caseIds}`);
        if (countsResponse.ok) {
          const countsData = await countsResponse.json();
          setDocumentCounts(countsData.counts);
        }
      }
    } catch (error) {
      console.error("Error fetching cases:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleCaseSelect = (caseId) => {
    setSelectedCases(prev =>
      prev.includes(caseId)
        ? prev.filter(id => id !== caseId)
        : [...prev, caseId]
    );
  };

  const handleFileUpload = async (event, caseId) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    setUploading(true);
    const formData = new FormData();
    for (let file of files) {
      formData.append('files', file);
    }
    formData.append('uploadedBy', localStorage.getItem('username') || 'System');

    try {
      const response = await fetch(`http://localhost:5000/cases/${caseId}/files`, {
        method: 'POST',
        body: formData
      });

      if (response.ok) {
        alert('Files uploaded successfully!');
        fetchCases(); // Refresh document counts
      } else {
        alert('Failed to upload files');
      }
    } catch (error) {
      console.error('Upload error:', error);
      alert('Upload failed');
    } finally {
      setUploading(false);
    }
  };

  const handleBulkUpload = async (event) => {
    const files = event.target.files;
    if (!files || files.length === 0 || selectedCases.length === 0) return;

    setBulkUploading(true);
    const formData = new FormData();
    for (let file of files) {
      formData.append('files', file);
    }
    formData.append('caseIds', JSON.stringify(selectedCases));
    formData.append('uploadedBy', localStorage.getItem('username') || 'System');
    formData.append('documentType', 'shared');

    try {
      const response = await fetch('http://localhost:5000/cases/upload-shared-document', {
        method: 'POST',
        body: formData
      });

      if (response.ok) {
        alert(`Documents uploaded successfully to ${selectedCases.length} similar cases!`);
        setSelectedCases([]); // Clear selection
        fetchCases(); // Refresh document counts
      } else {
        alert('Failed to upload shared documents');
      }
    } catch (error) {
      console.error('Bulk upload error:', error);
      alert('Bulk upload failed');
    } finally {
      setBulkUploading(false);
    }
  };

  if (loading) return <div>Loading similar cases...</div>;

  return (
    <div className="similar-cases-container">
      <h2>📋 Manage Documents for Similar Cases</h2>
      <p>Cases with the same title but different clients. Upload different documents for each client.</p>

      {/* Bulk Upload Section */}
      {selectedCases.length > 0 && (
        <div className="bulk-upload-section" style={{
          background: '#e3f2fd',
          padding: '15px',
          borderRadius: '8px',
          marginBottom: '20px',
          border: '2px solid #2196f3'
        }}>
          <h3>📤 Bulk Upload to Selected Cases ({selectedCases.length})</h3>
          <p>Upload documents that will be shared across all selected similar cases.</p>
          <input
            type="file"
            multiple
            onChange={handleBulkUpload}
            disabled={bulkUploading}
            accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png"
            style={{ marginRight: '10px' }}
          />
          {bulkUploading && <span>Uploading to {selectedCases.length} cases...</span>}
        </div>
      )}

      {cases.length === 0 ? (
        <p>No similar cases found.</p>
      ) : (
        <div className="similar-cases-grid">
          {cases.map(caseItem => (
            <div
              key={caseItem.id}
              className={`case-card ${selectedCases.includes(caseItem.id) ? 'selected' : ''}`}
              style={{
                border: selectedCases.includes(caseItem.id) ? '2px solid #4caf50' : '1px solid #ddd',
                backgroundColor: selectedCases.includes(caseItem.id) ? '#f8fff8' : 'white'
              }}
            >
              <div className="case-header">
                <input
                  type="checkbox"
                  checked={selectedCases.includes(caseItem.id)}
                  onChange={() => handleCaseSelect(caseItem.id)}
                  style={{ marginRight: '10px' }}
                />
                <h3>{caseItem.title}</h3>
                <span className="client-badge">{caseItem.client}</span>
              </div>

              <div className="case-info">
                <p><strong>ID:</strong> {caseItem.id}</p>
                <p><strong>Status:</strong> {caseItem.status}</p>
                <p><strong>Documents:</strong> {documentCounts[caseItem.id] || 0}</p>
              </div>

              <div className="upload-section">
                <label>Individual Upload:</label>
                <input
                  type="file"
                  multiple
                  onChange={(e) => handleFileUpload(e, caseItem.id)}
                  disabled={uploading}
                  accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png"
                />
                {uploading && <p>Uploading...</p>}
              </div>

              <button
                onClick={() => window.open(`/cases/${caseItem.id}`, '_blank')}
                className="view-case-btn"
              >
                View Case Details
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SimilarCasesDocumentManager;
