import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import ssImage from '../assets/AA.png';

const ClientBilling = () => {
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchInvoices();
  }, []);

  const fetchInvoices = async () => {
    try {
      const response = await fetch("http://localhost:5000/invoices");
      if (!response.ok) {
        throw new Error("Failed to fetch invoices");
      }
      const data = await response.json();
      // Filter invoices for the logged-in client
      const clientName = localStorage.getItem("clientName") || "John Doe"; // Default for demo
      const clientInvoices = data.filter(invoice => invoice.client === clientName);
      setInvoices(clientInvoices);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div>Loading billing information...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div style={{ padding: "20px", backgroundImage: `url(${ssImage})`, backgroundSize: 'cover', backgroundPosition: 'center', backgroundRepeat: 'no-repeat', minHeight: "100vh" }}>
      <div style={{ marginBottom: "20px" }}>
        <Link to="/client-dashboard">
          <button
            style={{
              padding: "10px 20px",
              background: "linear-gradient(135deg, #28a745 0%, #20c997 100%)",
              color: "white",
              border: "none",
              borderRadius: "8px",
              fontSize: "14px",
              fontWeight: "bold",
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              transition: "transform 0.3s ease"
            }}
            onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
            onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
          >
            ← Back to Dashboard
          </button>
        </Link>
      </div>
      <h2 style={{
        textAlign: "center",
        fontSize: "2.2rem",
        marginBottom: "30px",
        color: "white"
      }}>
        💳 My Billing
      </h2>

      {invoices.length === 0 ? (
        <div style={{
          textAlign: "center",
          padding: "40px",
          background: "rgba(255, 255, 255, 0.9)",
          borderRadius: "20px",
          boxShadow: "0 10px 30px rgba(0,0,0,0.1)"
        }}>
          <p style={{ fontSize: "1.2rem", color: "#666" }}>No invoices found.</p>
        </div>
      ) : (
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fill, minmax(350px, 1fr))",
          gap: "25px",
          padding: "0 20px"
        }}>
          {invoices.map(invoice => (
            <div key={invoice.id} style={{
              background: "linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%)",
              borderRadius: "20px",
              padding: "25px",
              boxShadow: "0 15px 35px rgba(0,0,0,0.1)",
              border: "1px solid rgba(255,255,255,0.2)",
              transition: "transform 0.3s ease, box-shadow 0.3s ease",
              cursor: "pointer"
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = "translateY(-5px)";
              e.currentTarget.style.boxShadow = "0 20px 45px rgba(0,0,0,0.15)";
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = "translateY(0)";
              e.currentTarget.style.boxShadow = "0 15px 35px rgba(0,0,0,0.1)";
            }}
            >
              <div style={{ marginBottom: "15px" }}>
                <h3 style={{
                  margin: "0 0 10px 0",
                  color: "#333",
                  fontSize: "1.4rem",
                  fontWeight: "bold"
                }}>
                  Invoice #{invoice.id}
                </h3>
                <div style={{
                  display: "inline-block",
                  padding: "6px 12px",
                  borderRadius: "20px",
                  fontSize: "0.85rem",
                  fontWeight: "bold",
                  background: invoice.status === "Paid"
                    ? "linear-gradient(135deg, #28a745, #20c997)"
                    : invoice.status === "Overdue"
                    ? "linear-gradient(135deg, #dc3545, #c82333)"
                    : "linear-gradient(135deg, #ffc107, #fd7e14)",
                  color: "white",
                  textTransform: "uppercase",
                  letterSpacing: "0.5px"
                }}>
                  {invoice.status}
                </div>
              </div>

              <div style={{ marginBottom: "15px" }}>
                <p style={{ margin: "8px 0", color: "#555", fontSize: "0.95rem" }}>
                  <strong style={{ color: "#333" }}>Case:</strong> {invoice.case_description || 'N/A'}
                </p>
                <p style={{ margin: "8px 0", color: "#555", fontSize: "0.95rem" }}>
                  <strong style={{ color: "#333" }}>Staff:</strong> {invoice.staff_handling || 'N/A'}
                </p>
                <p style={{ margin: "8px 0", color: "#555", fontSize: "0.95rem" }}>
                  <strong style={{ color: "#333" }}>Due Date:</strong> {invoice.dueDate || 'N/A'}
                </p>
              </div>

              <div style={{
                background: "linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%)",
                borderRadius: "15px",
                padding: "15px",
                border: "1px solid rgba(0,0,0,0.05)"
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "8px" }}>
                  <span style={{ fontWeight: "bold", color: "#333" }}>Total Amount:</span>
                  <span style={{ fontWeight: "bold", color: "#007bff", fontSize: "1.1rem" }}>₹{invoice.amount_to_pay}</span>
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "8px" }}>
                  <span style={{ color: "#666" }}>Amount Paid:</span>
                  <span style={{ color: "#28a745", fontWeight: "bold" }}>₹{invoice.amount_paid || '0.00'}</span>
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", borderTop: "1px solid rgba(0,0,0,0.1)", paddingTop: "8px" }}>
                  <span style={{ fontWeight: "bold", color: "#333" }}>Remaining:</span>
                  <span style={{
                    fontWeight: "bold",
                    color: invoice.remaining_amount > 0 ? "#dc3545" : "#28a745",
                    fontSize: "1.1rem"
                  }}>
                    ₹{invoice.remaining_amount || '0.00'}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ClientBilling;
