import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";

const Clients = () => {
  const [search, setSearch] = useState("");
  const [clientsData, setClientsData] = useState([]);
  const [casesData, setCasesData] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const advocateUsername = localStorage.getItem('username');
        if (!advocateUsername) {
          setClientsData([]);
          setCasesData([]);
          return;
        }

        // Fetch clients
        const clientsResponse = await fetch(`http://localhost:5000/clients?advocate_username=${encodeURIComponent(advocateUsername)}`);
        if (!clientsResponse.ok) {
          throw new Error("Failed to fetch clients");
        }
        const clientsData = await clientsResponse.json();
        setClientsData(clientsData);

        // Fetch cases
        const casesResponse = await fetch("http://localhost:5000/cases");
        if (!casesResponse.ok) {
          throw new Error("Failed to fetch cases");
        }
        const casesData = await casesResponse.json();
        setCasesData(casesData);
      } catch (err) {
        console.error("Error fetching data:", err);
      }
    };

    fetchData();
  }, []);

  const filteredClients = clientsData.filter(
    (c) =>
      c.name.toLowerCase().includes(search.toLowerCase()) ||
      (c.email && c.email.toLowerCase().includes(search.toLowerCase()))
  );

  const deleteClient = async (clientId) => {
    if (!window.confirm('Are you sure you want to delete this client? This action cannot be undone.')) {
      return;
    }

    const advocateUsername = localStorage.getItem('username');
    if (!advocateUsername) {
      alert('You must be logged in as an advocate to delete clients.');
      return;
    }

    try {
      const response = await fetch(`http://localhost:5000/clients/${clientId}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ advocateUsername }),
      });

      if (!response.ok) {
        // Try to parse error response
        try {
          const errorResult = await response.json();
          const errorMessage = errorResult.message || "Failed to delete client";
          alert(errorMessage);
        } catch (e) {
          alert(`Server error (${response.status}): ${response.statusText}`);
        }
        return;
      }

      const result = await response.json();
      if (result.success) {
        alert('Client deleted successfully!');
        // Refresh the data
        const fetchClients = async () => {
          try {
            const advocateUsername = localStorage.getItem('username');
            if (!advocateUsername) {
              setClientsData([]);
              return;
            }

            const response = await fetch(`http://localhost:5000/clients?advocate_username=${encodeURIComponent(advocateUsername)}`);
            if (!response.ok) {
              throw new Error("Failed to fetch clients");
            }
            const data = await response.json();
            setClientsData(data);
          } catch (err) {
            console.error("Error fetching clients:", err);
          }
        };
        fetchClients();
      } else {
        alert(result.message || "Failed to delete client");
      }
    } catch (error) {
      console.error('Network error:', error);
      alert('Unable to connect to server. Please check if the backend server is running.');
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        padding: "30px",
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      }}
    >
      {/* Header */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          background: "burlywood",
          padding: "20px 30px",
          borderRadius: "15px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)",
          marginBottom: "30px",
        }}
      >
        <h2 style={{ color: "#333", fontSize: "1.8rem", margin: 0 }}>👥 Client Management</h2>

        <Link
          to="/dashboard"
          style={{
            display: "inline-block",
            background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
            color: "white",
            padding: "10px 20px",
            borderRadius: "8px",
            fontWeight: "bold",
            textDecoration: "none",
            boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
            transition: "0.3s ease",
          }}
          onMouseEnter={(e) => (e.target.style.transform = "translateY(-3px)")}
          onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
        >
          ⬅️ Back to Dashboard
        </Link>
      </div>

      {/* Search */}
      <div
        style={{
          background: "white",
          padding: "20px",
          borderRadius: "10px",
          boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
          marginBottom: "25px",
        }}
      >
        <input
          type="search"
          placeholder="🔍 Search by name or email..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{
            width: "100%",
            padding: "12px",
            borderRadius: "8px",
            border: "1px solid #ccc",
            fontSize: "1rem",
          }}
        />
      </div>

      {/* Client List */}
      <div
        style={{
          background: "white",
          borderRadius: "15px",
          padding: "20px",
          boxShadow: "0 8px 25px rgba(0,0,0,0.1)",
        }}
      >
        {filteredClients.length === 0 ? (
          <p style={{ textAlign: "center", color: "#777" }}>No clients found.</p>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: "20px" }}>
            {filteredClients.map((client) => (
              <div
                key={client.id}
                style={{
                  background: "linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)",
                  padding: "20px",
                  borderRadius: "10px",
                  boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
                  transition: "0.3s ease",
                  position: "relative",
                }}
                onMouseEnter={(e) => (e.target.style.transform = "translateY(-5px)")}
                onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
              >
                <button
                  onClick={() => deleteClient(client.id)}
                  style={{
                    position: "absolute",
                    top: "10px",
                    right: "10px",
                    background: "linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)",
                    color: "white",
                    border: "none",
                    padding: "6px 10px",
                    borderRadius: "5px",
                    fontSize: "0.7rem",
                    fontWeight: "bold",
                    cursor: "pointer",
                    boxShadow: "0 2px 5px rgba(0,0,0,0.2)",
                    transition: "0.3s ease",
                  }}
                  onMouseEnter={(e) => (e.target.style.transform = "translateY(-2px)")}
                  onMouseLeave={(e) => (e.target.style.transform = "translateY(0)")}
                >
                  🗑️ Delete
                </button>
                <h3 style={{ margin: "0 0 10px 0", color: "#333" }}>{client.name}</h3>
                <p style={{ margin: "5px 0", color: "#666" }}>📧 {client.email}</p>
                <p style={{ margin: "5px 0", color: "#666" }}>📞 {client.phone}</p>
                <p style={{ margin: "5px 0", color: "#666" }}>🏠 {client.address}</p>
                {client.advocate_name && (
                  <p style={{ margin: "5px 0", color: "#28a745", fontWeight: "bold" }}>
                    👨‍⚖️ Advocate: {client.advocate_name} ({client.advocate_username})
                  </p>
                )}
                {/* Show Original Suit for Civil cases */}
                {casesData.filter(c => c.client === client.name && c.case_type === "Civil" && c.original_suit).map(c => (
                  <p key={c.id} style={{ margin: "5px 0", color: "#007bff", fontWeight: "bold" }}>
                    📄 Original Suit: {c.original_suit}
                  </p>
                ))}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Clients;
