import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Cases.css";

const AddCase = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    case_id: "",
    title: "",
    case_type: "Civil",
    fir_number: "",
    court_name: "",
    accused_name: "",
    ipc_sections: "",
    original_suit: "",
    status: "Open",
    nextHearing: "",
    client: ""
  });
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [successMessage, setSuccessMessage] = useState("");

  const fetchClients = useCallback(async () => {
    try {
      const response = await fetch("http://localhost:5000/clients");
      if (!response.ok) {
        throw new Error("Failed to fetch clients");
      }
      const data = await response.json();
      setClients(data);
    } catch (err) {
      console.error("Error fetching clients:", err);
    }
  }, []);

  useEffect(() => {
    fetchClients();
  }, [fetchClients]);

  const handleInputChange = useCallback((e) => {
    const { name, value } = e.target;
    setFormData(prev => {
      const updatedData = {
        ...prev,
        [name]: value
      };
      // Clear irrelevant fields based on case_type
      if (name === "case_type") {
        if (value === "Civil") {
          updatedData.fir_number = "";
          updatedData.ipc_sections = "";
        } else {
          updatedData.original_suit = "";
        }
      }
      return updatedData;
    });
    // Clear error and success message when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ""
      }));
    }
    if (successMessage) {
      setSuccessMessage("");
    }
  }, [errors, successMessage]);

  const validateForm = useCallback(() => {
    const newErrors = {};

    if (!formData.title.trim()) {
      newErrors.title = "Case title is required";
    }

    if (!formData.status) {
      newErrors.status = "Case status is required";
    }

    if (!formData.client) {
      newErrors.client = "Client is required";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [formData]);

  const handleSubmit = useCallback(async (e) => {
    e.preventDefault();
    e.stopPropagation();

    if (!validateForm()) {
      return;
    }

    setLoading(true);

    console.log('Submitting case data:', formData);

    try {
      const response = await fetch("http://localhost:5000/cases", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      console.log('Response status:', response.status);
      const result = await response.json();
      console.log('Response data:', result);

      if (result.success) {
        // Show success message and stay on the page
        setSuccessMessage("Case added successfully!");
        // Reset form after successful submission
        setFormData({
          case_id: "",
          title: "",
          case_type: "Civil",
          fir_number: "",
          court_name: "",
          accused_name: "",
          ipc_sections: "",
          original_suit: "",
          status: "Open",
          nextHearing: "",
          client: ""
        });
        // Clear success message after 3 seconds
        setTimeout(() => setSuccessMessage(""), 3000);
      } else {
        alert(`Failed to add case: ${result.message}`);
      }
    } catch (error) {
      console.error("Error adding case:", error);
      alert("An error occurred while adding the case. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [formData, validateForm]);

  const clientOptions = useMemo(() =>
    clients.map(client => (
      <option key={client.id} value={client.name}>
        {client.name}
      </option>
    )), [clients]
  );

  return (
    <div className="cases-container">
      <header className="cases-header sticky-header">
        <div className="back-button-wrapper">
          <Link to="/cases" className="back-button" aria-label="Back to Cases">
            ⬅️ Back to Cases
          </Link>
        </div>

        <div className="cases-header-info">
          <h1>➕ Add New Case</h1>
          <p>Enter the details for the new legal case</p>
        </div>
      </header>

      <main>
        {successMessage && (
          <div className="success-message" style={{
            backgroundColor: '#d4edda',
            color: '#155724',
            padding: '10px',
            marginBottom: '20px',
            border: '1px solid #c3e6cb',
            borderRadius: '4px',
            textAlign: 'center'
          }}>
            {successMessage}
          </div>
        )}
        <div className="add-case-form-container">
          <div className="add-case-form">
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="case_id">Case ID</label>
                <input
                  type="text"
                  id="case_id"
                  name="case_id"
                  value={formData.case_id}
                  onChange={handleInputChange}
                  placeholder="Enter case ID (optional)"
                />
              </div>

              <div className="form-group">
                <label htmlFor="title">Case Title *</label>
                <input
                  type="text"
                  id="title"
                  name="title"
                  value={formData.title}
                  onChange={handleInputChange}
                  placeholder="Enter case title"
                  required
                />
                {errors.title && <span className="error-message">{errors.title}</span>}
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="case_type">Case Type</label>
                <select
                  id="case_type"
                  name="case_type"
                  value={formData.case_type}
                  onChange={handleInputChange}
                >
                  <option value="">Select case type</option>
                  <option value="Criminal">Criminal</option>
                  <option value="Civil">Civil</option>
                  <option value="Family">Family</option>
                  <option value="Corporate">Corporate</option>
                  <option value="Property">Property</option>
                  <option value="Other">Other</option>
                </select>
              </div>
            </div>

            {formData.case_type !== "Civil" && (
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="fir_number"></label>
                  <input
                    type="text"
                    id="fir_number"
                    name="fir_number"
                    value={formData.fir_number}
                    onChange={handleInputChange}
                    placeholder="Enter FIR Number/Original Suit (e.g., 123/2024)"
                  />
                </div>
                <div className="form-group">
                  <label htmlFor="original_suit">Original Suit</label>
                  <input
                    type="text"
                    id="original_suit"
                    name="original_suit"
                    value={formData.original_suit}
                    onChange={handleInputChange}
                    placeholder="Enter FIR Number/Original Suit (e.g., 123/2024)"
                  />
                </div>
              </div>
            )}

            {formData.case_type === "Civil" && (
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="original_suit">Original Suit</label>
                  <input
                    type="text"
                    id="original_suit"
                    name="original_suit"
                    value={formData.original_suit}
                    onChange={handleInputChange}
                    placeholder="Enter FIR Number/Original Suit (e.g., 123/2024)"
                  />
                </div>
              </div>
            )}

            {formData.case_type !== "Civil" && (
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="ipc_sections">IPC Sections</label>
                  <input
                    type="text"
                    id="ipc_sections"
                    name="ipc_sections"
                    value={formData.ipc_sections}
                    onChange={handleInputChange}
                    placeholder="Enter IPC sections (comma separated)"
                  />
                </div>
              </div>
            )}

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="court_name">Court Name</label>
                <input
                  type="text"
                  id="court_name"
                  name="court_name"
                  value={formData.court_name}
                  onChange={handleInputChange}
                  placeholder="Enter court name"
                />
              </div>

              <div className="form-group">
                <label htmlFor="accused_name">Accused Name</label>
                <input
                  type="text"
                  id="accused_name"
                  name="accused_name"
                  value={formData.accused_name}
                  onChange={handleInputChange}
                  placeholder="Enter accused name"
                />
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="status">Case Status *</label>
                <select
                  id="status"
                  name="status"
                  value={formData.status}
                  onChange={handleInputChange}
                  required
                >
                  <option value="Open">Open</option>
                  <option value="Closed">Closed</option>
                  <option value="Pending">Pending</option>
                  <option value="In Progress">In Progress</option>
                </select>
                {errors.status && <span className="error-message">{errors.status}</span>}
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label htmlFor="client">Client *</label>
                <select
                  id="client"
                  name="client"
                  value={formData.client}
                  onChange={handleInputChange}
                  required
                >
                  <option value="">Select a client</option>
                  {clientOptions}
                </select>
                {errors.client && <span className="error-message">{errors.client}</span>}
              </div>

              <div className="form-group">
                <label htmlFor="nextHearing">Next Hearing Date</label>
                <input
                  type="date"
                  id="nextHearing"
                  name="nextHearing"
                  value={formData.nextHearing}
                  onChange={handleInputChange}
                />
              </div>
            </div>



            <div className="form-actions">
              <button
                type="button"
                onClick={() => navigate("/cases")}
                className="cancel-button"
              >
                Cancel
              </button>
              <button
                type="button"
                disabled={loading}
                className="submit-button"
                onClick={handleSubmit}
              >
                {loading ? "Adding Case..." : "Add Case"}
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default AddCase;
